// 由 人工分析唐宋元明清节气意象.xlsx 自动生成（2026-11-26 修订版：四季各6节气）
window.JIEQI_DATA={"terms": [{"name": "立春", "season": "春", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·立春正月节", "text": "春冬移律吕，天地换星霜。\n冰泮游鱼跃，和风待柳芳。\n早梅迎雨水，残雪怯朝阳。\n万物含新意，同欢圣日长。", "img": "春风 柳 梅 残雪"}, {"dyn": "唐", "poet": "杜甫", "title": "立春", "text": "春日春盘细生菜，忽忆两京梅发时。\n盘出高门行白玉，菜传纤手送青丝。\n巫峡寒江那对眼，杜陵远客不胜悲。\n此身未知归定处，呼儿觅纸一题诗。", "img": "梅 春日"}, {"dyn": "唐", "poet": "张九龄", "title": "立春日晨起对积雪", "text": "忽对林亭雪，瑶华处处开。\n今年迎气始，昨夜伴春回。\n玉润窗前竹，花繁院里梅。\n东郊斋祭所，应见五神来。", "img": "雪 竹 梅"}, {"dyn": "唐", "poet": "韦庄", "title": "立春", "text": "青帝东来日驭迟，暖烟轻逐晓风吹。\n罽袍公子樽前觉，锦帐佳人梦里知。\n雪圃乍开红菜甲，彩幡新翦绿杨丝。\n殷勤为作宜春曲，题向花笺帖绣楣。", "img": "晓风（春风）  杨丝（杨柳）"}, {"dyn": "宋", "poet": "张栻", "title": "立春偶成", "text": "律回岁晚冰霜少，春到人间草木知。\n便觉眼前生意满，东风吹水绿参差。", "img": "冰霜 东风"}, {"dyn": "宋", "poet": "陆游", "title": "立春", "text": "绍熙又见四番春，春日春盘节物新。\n独酌三杯愁对影，例添一岁老催人。\n菊芽冒土如争出，柳色摇村已渐匀。\n身是兰亭山下客，未容逸少擅清真。", "img": "菊 柳"}, {"dyn": "宋", "poet": "苏轼", "title": "减字木兰花·立春", "text": "春牛春杖，无限春风来海上。\n便与春工，染得桃红似肉红。\n春幡春胜，一阵春风吹酒醒。\n不似天涯，卷起杨花似雪花。", "img": "春风 桃 杨花"}, {"dyn": "宋", "poet": "朱淑真", "title": "立春古律", "text": "停杯不饮待春来，和气先春动六街。\n生菜乍挑宜卷饼，罗幡旋剪称联钗。\n休论残腊千重恨，管入新年百事谐。\n从此对花并对景，尽拘风月入诗怀。", "img": "残腊"}, {"dyn": "宋", "poet": "邓深", "title": "腊月立春", "text": "柳条弄色舞轻风，不与寻常岁暮同。\n寒气望尘先敛退，阳和和轫已交通。\n菜丝盘玉还充席，幡字花房正代功。\n首迓东皇须痛饮，可能无句著新工。", "img": "柳条 寒气"}, {"dyn": "宋", "poet": "孔平仲", "title": "立春", "text": "春风不择地，亦到海边城。\n衮衮衣冠会，喧喧鼓吹迎。\n为牛一何苦，举世尽相争。\n旅客心偏静，停杯想耦耕。", "img": "春风"}, {"dyn": "元", "poet": "王冕", "title": "立春日", "text": "葭吹六管动飞灰，便觉春从地底回。\n宁须生菜传纤手，且引春风入瓦杯。\n天北天南问音信，故人何处寄寒梅？", "img": "葭 春风 寒梅"}, {"dyn": "元", "poet": "贯云石", "title": "清江引·立春", "text": "金钗影摇春燕斜，木杪生春叶。\n水塘春始波，火候春初热。\n土牛儿载将春到也。", "img": "燕 春叶"}], "stats": [], "emotion": "这十二首立春诗词以梅、柳、残雪、春风等自然物候意象为载体，情感层次丰富。冰雪消融、早梅绽放、柳条初萌的初春景象，常常唤起诗人对阳气回升、万物萌生的欣喜，是对时序更迭、生机复苏的安静体察；当同样的物候景致落入漂泊者的视野，便生出反差，杜甫借春日梅花、春盘风物追忆旧日风光，在初春盛景之下藏着羁旅难归的悲慨，陆游、王冕也依托春风、寒梅，寄寓岁华渐长、思念故人的怅惘。还有不少诗人面对初萌草木，心境平和冲淡，于细微物候里接纳时序轮转，生出对新岁安稳的朴素期许，个体不同的人生境遇，让同一组初春物候承载了截然不同的情绪。", "culture": "这些自然物候意象承载着古人独特的时节认知与审美传统。立春处在冬春交界，残雪、寒梅、初柳共同构成 “寒中孕生” 的物候图景，是古人观察阴阳消长的直观依据，草木萌动、冰泮鱼跃的细微变化，印证着地气回升、阳气始发的时序规律，暗含天人相应的时间观念。同时这套物候意象也形成古典独有的审美范式，不同于盛春繁花满眼的热烈，立春偏爱捕捉寒未尽、春方生的含蓄生机，诗人从梅破残雪、柳吐新芽的细微景象里感知春意，将自然物候的变化作为岁时更新的信号，把天地节律的流转，转化为可感知、可吟咏的诗意审美。"}, {"name": "雨水", "season": "春", "poems": [{"dyn": "唐", "poet": "杜甫", "title": "春夜喜雨", "text": "好雨知时节，当春乃发生。\n随风潜入夜，润物细无声。\n野径云俱黑，江船火独明。\n晓看红湿处，花重锦官城。", "img": "春雨 花"}, {"dyn": "唐", "poet": "韩愈", "title": "早春呈水部张十八员外", "text": "天街小雨润如酥，草色遥看近却无。\n最是一年春好处，绝胜烟柳满皇都。", "img": "春雨 柳"}, {"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·雨水正月中", "text": "雨水洗春容，平田已见龙。\n祭鱼盈浦屿，归雁过山峰。\n云色轻还重，风光淡又浓。\n向春入二月，花色影重重。", "img": "春雨 花"}, {"dyn": "唐", "poet": "李商隐", "title": "春雨", "text": "怅卧新春白袷衣，白门寥落意多违。\n红楼隔雨相望冷，珠箔飘灯独自归。\n远路应悲春晼晚，残霄犹得梦依稀。\n玉铛缄札何由达，万里云罗一雁飞。", "img": "春雨"}, {"dyn": "唐", "poet": "孟郊", "title": "春雨后", "text": "昨夜一霎雨，天意苏群物。\n何物最先知，虚庭草争出。", "img": "春雨"}, {"dyn": "唐", "poet": "张志和", "title": "渔歌子", "text": "西塞山前白鹭飞，桃花流水鳜鱼肥。\n青箬笠，绿蓑衣，斜风细雨不须归。", "img": "春雨 桃花"}, {"dyn": "宋", "poet": "陆游", "title": "临安春雨初霁", "text": "世味年来薄似纱，谁令骑马客京华。\n小楼一夜听春雨，深巷明朝卖杏花。\n矮纸斜行闲作草，晴窗细乳戏分茶。\n素衣莫起风尘叹，犹及清明可到家。", "img": "春雨 杏花"}, {"dyn": "宋", "poet": "志南", "title": "绝句", "text": "古木阴中系短篷，杖藜扶我过桥东。\n沾衣欲湿杏花雨，吹面不寒杨柳风。", "img": "杏花 春雨 杨柳 寒风"}, {"dyn": "宋", "poet": "邵雍", "title": "春雨吟", "text": "春雨细如丝，如丝霡霂时。\n如何一霶霈，万物尽熙熙。", "img": "春雨"}, {"dyn": "宋", "poet": "秦观", "title": "好事近·梦中作", "text": "春路雨添花，花动一山春色。\n行到小溪深处，有黄鹂千百。\n飞云当面化龙蛇，夭矫转空碧。\n醉卧古藤阴下，了不知南北。", "img": "春雨 花 黄鹂"}, {"dyn": "宋", "poet": "欧阳修", "title": "采桑子·群芳过后西湖好", "text": "群芳过后西湖好，狼籍残红。\n飞絮濛濛，垂柳阑干尽日风。\n笙歌散尽游人去，始觉春空。\n垂下帘栊，双燕归来细雨中。", "img": "春雨 垂柳 燕"}], "stats": [], "emotion": "这一组雨水、春雨主题诗词以春雨、花、柳为核心自然物候意象，情感呈现出鲜明的两面性。多数诗作借春雨滋养草木、催开花朵的景象，抒发对春日生机的喜爱与赞美，杜甫、韩愈笔下的春雨柔和温润，唤醒万物，满是对时节造化的欣喜；志南、陆游等人在春雨、杨柳、杏花的景致里，寄寓闲适自在的心境，或是客居之中淡淡的松弛感。而李商隐的诗作另辟一重基调，绵绵春雨化作清冷的背景，烘托相隔难逢的孤寂与怅惘，细雨朦胧的春景，和诗人寥落失意的心境相互映衬，温柔雨景之下藏着相思无望的愁绪。春雨这同一物象，既能承载欣悦舒展的情绪，也能衬出独处怀人的悲凉。", "culture": "春雨是雨水节气标志性的物候符号，古人将春雨视作天地生发之气的载体，“润物” 是雨水意象独有的内涵，雨水降临，滋养百草、催开春花，代表阳气持续升腾，是春耕即将开启的信号，体现顺应天时、天人相感的时间认知。同时春雨搭配柳、杏花、桃花、黄鹂等意象，构成古典诗词里典型的江南春日审美图景，细雨朦胧、花木含润，形成含蓄柔和的审美风格。春雨也慢慢沉淀为古典抒情传统里的经典意象，它不只是自然降水，更是春的信使，既关联农时生计，也成为文人抒发闲情、寄托离愁的诗意载体。"}, {"name": "惊蛰", "season": "春", "poems": [{"dyn": "唐", "poet": "韦应物", "title": "观田家", "text": "微雨众卉新，一雷惊蛰始。\n田家几日闲，耕种从此起。\n丁壮俱在野，场圃亦就理。\n归来景常晏，饮犊西涧水。\n饥劬不自苦，膏泽且为喜。\n仓廪无宿储，徭役犹未已。\n方惭不耕者，禄食出闾里。", "img": "惊蛰雨 春雷"}, {"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·惊蛰二月节", "text": "阳气初惊蛰，韶光大地周。\n桃花开蜀锦，鹰老化春鸠。\n时候争催迫，萌芽㸦矩修。\n人间务生事，耕种满田畴。", "img": "桃花 春鸠"}, {"dyn": "唐", "poet": "刘长卿", "title": "惊蛰", "text": "陌上杨柳方竞春，塘中鲫鲥早成荫。\n忽闻天公霹雳声，禽兽虫豸倒乾坤。", "img": "杨柳 春雷"}, {"dyn": "宋", "poet": "范成大", "title": "秦楼月·浮云集", "text": "浮云集，轻雷隐隐初惊蛰。\n初惊蛰，鹁鸠鸣怒，绿杨风急。\n玉炉烟重香罗浥，拂墙浓杏燕支湿。\n燕支湿，花梢缺处，画楼人立。", "img": "春雷 鹁鸠 杨柳 春风 杏花 燕"}, {"dyn": "宋", "poet": "陆游", "title": "春晴泛舟", "text": "儿童莫笑是陈人，湖海春回发兴新。\n雷动风行惊蛰户，天开地辟转鸿钧。\n鳞鳞江色涨石黛，嫋嫋柳丝摇麴尘。\n欲上兰亭却回棹，笑谈终觉愧清真。", "img": "春雷 杨柳"}, {"dyn": "宋", "poet": "仇远", "title": "惊蛰日雷", "text": "坤宫半夜一声雷，蛰户花房晓已开。\n野阔风高吹烛灭，电明雨急打窗来。\n顿然草木精神别，自是寒暄气候催。\n惟有石龟并木雁，守株不动任春回。", "img": "春雷"}, {"dyn": "宋", "poet": "苏辙", "title": "游景仁东园", "text": "新春甫惊蛰，草木犹未知。\n高人静无事，颇怪春来迟。\n肩舆出东郊，轻裘试朝曦。\n百草招生意，乔松解寒姿。\n尺书招友生，冠盖溢通逵。\n人生瞬息间，幸此休暇时。\n浊酒瀹浮蚁，嘉蔬荐柔荑。", "img": "百草 乔松"}, {"dyn": "宋", "poet": "张元干", "title": "甲戌正月十四日书所见来日惊蛰节", "text": "老去何堪节物催，放灯中夜忽奔雷。\n一声大震龙蛇起，蚯蚓虾蟆也出来。", "img": "春雷 蚯蚓"}, {"dyn": "宋", "poet": "陈允平", "title": "山房", "text": "轩窗四面开，风送海云来。\n一阵催花雨，数声惊蛰雷。\n蜗涎明石凳，蟹舍傍江隈。\n一夜春涛急，源头活水来。", "img": "春雷 春汛"}, {"dyn": "清", "poet": "张英", "title": "山中即事十二首·其四", "text": "烈侯祠畔酒旗斜，谷口深林处士家。\n一雨才过惊蛰节，溪山到处是梅花。", "img": "惊蛰雨 梅花"}], "stats": [], "emotion": "惊蛰诗词以春雷、惊蛰雨、桃花、杨柳、鸠鸟等物候意象为依托，情感层次分明。春雷震起、蛰虫苏醒、花木抽芽的景象，大多带出诗人对阳气振奋、春气勃发的赞叹，田家诗里还饱含农人盼雨春耕、喜得膏泽的质朴欢欣；部分诗作在春雷催动时序的张力之下，生出对时光催迫的感慨，也有文人趁春日出游、邀约友人，享受春日闲暇的悠然。也有诗人在惊雷春雨的喧闹春景里，静看万物苏醒，对照自身，生出不事劳作的自省与愧疚，自然物候的动静变化，映照出不同身份者的心境。", "culture": "春雷是惊蛰最核心的物候标识，古人认为雷声震开蛰伏的虫兽，代表阳气冲破阴寒，天地阴阳格局发生转变，是时序轮转极具力量感的节点。惊蛰物候紧密关联农耕传统，雷起雨至、万物复苏便是春耕开启的信号，诗词里的耕种、田畴意象，承载着顺应天时、务本农耕的古老观念。同时春雷、鸣鸠、初花、杨柳组合，形成和立春、春雨截然不同的物候审美：不再是含蓄隐忍的初生春意，而是惊雷破寒、万物惊动的动态生机，以动静相激的物象，展现春日力量感，也成为文人感知天地气机变化、观照人间农事的诗意载体。"}, {"name": "春分", "season": "春", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏二十四气诗·春分二月中", "text": "二气莫交争，春分雨处行。\n雨来看电影，云过听雷声。\n山色连天碧，林花向日明。\n梁间玄鸟语，欲似解人情。", "img": "春雨 春雷 花 鸟"}, {"dyn": "唐", "poet": "杜牧", "title": "村行", "text": "春半南阳西，柔桑过村坞。\n娉娉垂柳风，点点回塘雨。\n蓑唱牧牛儿，篱窥茜裙女。\n半湿解征衫，主人馈鸡黍。", "img": "垂柳 春雨"}, {"dyn": "唐", "poet": "刘长卿", "title": "春分", "text": "日月阴阳两均天，玄鸟不辞桃花寒。\n从来今日竖鸡子，川上良人放纸鸢。", "img": "桃花 纸鸢"}, {"dyn": "唐", "poet": "崔融", "title": "和宋之问寒食题黄梅临江驿", "text": "春分自淮北，寒食渡江南。\n忽见浔阳水，疑是宋家潭。\n明主阍难叫，孤臣逐未甘。\n抚装那及远，回首望边岚。", "img": "春汛"}, {"dyn": "宋", "poet": "徐铉", "title": "春分日", "text": "仲春初四日，春色正中分。\n绿野徘徊月，晴天断续云。\n燕飞犹个个，花落已纷纷。\n思妇高楼晚，歌声不可闻。", "img": "燕 花"}, {"dyn": "宋", "poet": "苏轼", "title": "癸丑春分后雪", "text": "雪入春分省见稀，半开桃李不胜威。\n应惭落地梅花识，却作漫天柳絮飞。\n不分东君专节物，故将新巧发阴机。\n従今造物尤难料，更暖须留御腊衣。", "img": "桃花 李花"}, {"dyn": "宋", "poet": "邵雍", "title": "乐春吟", "text": "四时唯爱春，春更爱春分。\n有暖温存物，无寒著莫人。\n好花方蓓蕾，美酒正轻醇。\n安乐窝中客，如何不半醺。", "img": "花"}, {"dyn": "宋", "poet": "欧阳修", "title": "阮郎归·南园春半踏青时", "text": "南园春半踏青时，风和闻马嘶。\n青梅如豆柳如眉，日长蝴蝶飞。\n花露重，草烟低，人家帘幕垂。\n秋千慵困解罗衣，画堂双燕归。", "img": "青梅 柳 蝴蝶 花草 燕"}, {"dyn": "宋", "poet": "欧阳修", "title": "踏莎行·雨霁风光", "text": "雨霁风光，春分天气，千花百卉争明媚。\n画梁新燕一双双，玉笼鹦鹉愁孤睡。\n薜荔依墙，莓苔满地，青楼几处歌声丽。\n蓦然旧事上心来，无言敛皱眉山翠。", "img": "春雨 花卉 燕 青苔"}, {"dyn": "清", "poet": "宋琬", "title": "春日田家", "text": "野田黄雀自为群，山叟相过话旧闻。\n夜半饭牛呼妇起，明朝种树是春分。", "img": "黄雀"}], "stats": [], "emotion": "春分诗词依托春雨、春花、飞燕、垂柳等物候意象铺展心绪。半数作品沉醉于春分阴阳均衡、春光匀和的景致，在繁花、飞燕、和风里流露踏青赏春的愉悦，或是乡间农人顺应时节、准备种树劳作的朴实安然；也有诗作借落花纷飞、燕影来去的景象带出感伤，春日盛景之下，藏着思妇怀远、旧事萦怀的淡淡惆怅，还有逐臣漂泊途中，面对平分春色而生的孤苦失意。均衡的春光本身是中性的背景，随诗人境遇不同，生出闲适、欢喜或是怅惘多种情绪。", "culture": "春分是阴阳均分、昼夜等长的特殊时序节点，诗词中的物候书写承载着古人对天地二气平衡的认知，桃花绽放、燕子归来、草木舒展，都是仲春阳气稳步铺展的标志。春分也沉淀了丰富的民俗符号，竖蛋、放纸鸢、踏青、春分种树等习俗和自然物候相融，体现顺时而动的生活方式。在审美上，它不同于惊蛰惊雷破寒的激荡，也不似立春含蓄的初萌，是春色铺陈开来、冷暖相宜的平和之美，平分的春光，也成为文人感知时序、安放闲情与愁思的诗意载体。"}, {"name": "清明", "season": "春", "poems": [{"dyn": "唐", "poet": "杜牧", "title": "清明", "text": "清明时节雨纷纷，路上行人欲断魂。\n借问酒家何处有？牧童遥指杏花村。", "img": "清明雨"}, {"dyn": "唐", "poet": "韩翃", "title": "寒食", "text": "春城无处不飞花，寒食东风御柳斜。\n日暮汉宫传蜡烛，轻烟散入五侯家。", "img": "花 东风 柳树"}, {"dyn": "唐", "poet": "杜甫", "title": "清明二首·其一", "text": "朝来新火起新烟，湖色春光净客船。\n绣羽衔花他自得，红颜骑竹我无缘。\n胡童结束还难有，楚女腰肢亦可怜。\n不见定王城旧处，长怀贾傅井依然。", "img": "花 竹"}, {"dyn": "宋", "poet": "黄庭坚", "title": "清明", "text": "佳节清明桃李笑，野田荒冢只生愁。\n雷惊天地龙蛇蛰，雨足郊原草木柔。\n人乞祭余骄妾妇，士甘焚死不公侯。\n贤愚千载知谁是，满眼蓬蒿共一丘。", "img": "桃花 李花 春雷 清明雨 蓬蒿"}, {"dyn": "宋", "poet": "高翥", "title": "清明", "text": "南北山头多墓田，清明祭扫各纷然。\n纸灰飞作白蝴蝶，泪血染成红杜鹃。\n日落狐狸眠冢上，夜归儿女笑灯前。\n人生有酒须当醉，一滴何曾到九泉。", "img": "纸灰"}, {"dyn": "宋", "poet": "王禹偁", "title": "清明", "text": "无花无酒过清明，兴味萧然似野僧。\n昨日邻家乞新火，晓窗分与读书灯。", "img": "花 酒"}, {"dyn": "宋", "poet": "程颢", "title": "郊行即事", "text": "芳草绿野恣行事，春入遥山碧四周。\n兴逐乱红穿柳巷，固因流水坐苔矶。\n莫辞盏酒十分劝，只恐风花一片红。\n况是清明好天气，不妨游衍莫忘归。", "img": "芳草"}, {"dyn": "宋", "poet": "吴惟信", "title": "苏堤清明即事", "text": "梨花风起正清明，游子寻春半出城。\n日暮笙歌收拾去，万株杨柳属流莺。", "img": "梨花 杨柳 流莺（黄莺）"}, {"dyn": "宋", "poet": "苏轼", "title": "望江南·超然台作", "text": "春未老，风细柳斜斜。\n试上超然台上看，半壕春水一城花。\n烟雨暗千家。\n寒食后，酒醒却咨嗟。\n休对故人思故国，且将新火试新茶。\n诗酒趁年华。", "img": "春风 杨柳 清明雨"}, {"dyn": "明", "poet": "高启", "title": "清明呈馆中诸公", "text": "新烟著柳禁垣斜，杏酪分香俗共夸。\n白下有山皆绕郭，清明无客不思家。\n卞侯墓上迷芳草，卢女门前映落花。\n喜得故人同待诏，拟沽春雨醉京华。", "img": "杨柳 春雨"}, {"dyn": "明", "poet": "高启", "title": "送陈秀才还沙上省墓", "text": "满衣血泪与尘埃，乱后还乡亦可哀。\n风雨梨花寒食过，几家坟上子孙来？", "img": "春风 春雨"}], "stats": [], "emotion": "清明诗词以清明雨、杨柳、繁花、芳草等物候意象为底色，情感自带悲喜交织的特质。绵绵细雨、荒冢蓬蒿、纷飞纸灰，牵引出生人追思逝者的沉痛悲凉，饱含对生死无常的感慨；而春日杨柳、梨花、桃李盛放，城郊游春、笙歌相伴的景象，又流露出游赏春光的闲适舒展。不少诗人在两种情绪之间辗转，或是借清明风物抒发客居怀乡、故国难寻的怅惘，春日盛景与墓前哀思相互对照，欢愉与悲戚并存，构成清明独有的复杂情感。", "culture": "清明处在暮春时节，春雨、杨柳、梨花是标志性物候，草木繁茂、雨水丰足，体现阳气走向鼎盛的时序变化。清明融合寒食传统，新火、祭扫、踏青并行，一边是祭祖追远的礼俗，承载慎终追远的伦理观念，一边是出城游春、宴饮寻欢的民俗，暗含顺应春气、舒展身心的理念。物候生机与祭祀哀思相融，形成独有的审美，春光越是鲜活，越衬出对生命逝去的思考，让清明成为连通自然时序、宗族礼祭与个体生命感悟的特殊节气。"}, {"name": "谷雨", "season": "春", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·谷雨三月中", "text": "谷雨春光晓，山川黛色青。\n叶间鸣戴胜，泽水长浮萍。\n暖屋生蚕蚁，喧风引麦葶。\n鸣鸠徒拂羽，信矣不堪听。", "img": "浮萍 麦葶 鹁鸠"}, {"dyn": "唐", "poet": "曹邺", "title": "老圃堂", "text": "邵平瓜地接吾庐，谷雨干时手自锄。\n昨日春风欺不在，就床吹落读残书。", "img": "谷雨 春风"}, {"dyn": "唐", "poet": "齐己", "title": "谢中上人寄茶", "text": "春山谷雨前，并手摘芳烟。\n绿嫩难盈笼，清和易晚天。\n且招邻院客，试煮落花泉。\n地远劳相寄，无来又隔年。", "img": "谷雨"}, {"dyn": "宋", "poet": "朱槔", "title": "谷雨", "text": "天点纷林际，虚檐写梦中。\n明朝知谷雨，无策禁花风。\n石渚收机巧，烟蓑建事功。\n越禽牢闭口，吾道寄天公。", "img": "谷雨"}, {"dyn": "宋", "poet": "黄庭坚", "title": "见二十弟倡和梦得梅复次韵", "text": "落絮游丝三月候，风吹雨洗一城花。\n未知东郭清明酒，何似西窗谷雨茶。", "img": "春风 谷雨"}, {"dyn": "宋", "poet": "欧阳修", "title": "尝新茶呈圣俞（节选）", "text": "万木寒痴睡不醒，惟有此树先萌芽。\n乃知此为最灵物，宜其独得天地之英华。\n鄙哉谷雨枪与旗，多不足贵如刈麻。", "img": "树芽 谷雨"}, {"dyn": "宋", "poet": "仇远", "title": "浣溪沙", "text": "红紫妆林绿满池，游丝飞絮两依依。\n正当谷雨弄晴时。\n射鸭矮阑苍藓滑，画眉小槛晚花迟。\n一年弹指又春归。", "img": "谷雨 苍藓"}, {"dyn": "明", "poet": "方太古", "title": "谷雨", "text": "春事阑珊酒病瘳，山家谷雨早茶收。\n花前细细风双蝶，林外时时雨一鸠。\n碧海丹丘无鹤驾，绿蓑青笠有渔舟。\n尘埃漫笑浮生梦，岘首于今薄试游。", "img": "谷雨 蝴蝶 鹁鸠"}, {"dyn": "金末元初", "poet": "元好问", "title": "溪童", "text": "溪童相对采椿芽，指似阳坡说种瓜。\n想是近山营马少，青林深处有人家。", "img": "椿芽"}, {"dyn": "明", "poet": "唐寅", "title": "牡丹图", "text": "谷雨花枝号鼠姑，戏拈彤管画成图。\n平康脂粉知多少，可有相同颜色无。", "img": "谷雨"}], "stats": [], "emotion": "谷雨诗词以鹁鸠、浮萍、麦葶、蝴蝶、椿芽等暮春物候为依托，情绪多带着春将尽的淡淡惜春之感。诗人或是沉醉于谷雨晴日、草木丰茂的清和景致，在采茶、锄地、采摘椿芽的乡居日常里感受闲适自在；或是面对落花飞絮、春事将阑的景象，生出春光短暂、时序匆匆的怅惋。也有诗人于山野风物间安放本心，看淡俗世纷扰，借谷雨时节的田园景象抒发恬淡自守的心境，暮春蓬勃的草木生机与春归的惋惜交织在一起。", "culture": "谷雨是春季最后一个节气，鹁鸠鸣、浮萍生、麦葶舒展、蚕事兴起，标志春气将尽、万物走向丰长，是由春向夏过渡的物候信号。谷雨和农事紧密相连，采茶、种瓜、锄田、育蚕都是此时的节令活动，承载着古人顺时劳作、重视农桑的农耕观念。同时谷雨也形成独有的暮春审美，不同于仲春繁花竞放，它的景致是绿肥红瘦，在草木繁盛、絮飞花迟的景象里，藏着古人对春时落幕、时序循环的感知，将田园劳作、山野闲趣和时节流转的体悟融为一体。"}, {"name": "立夏", "season": "夏", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·立夏四月节", "text": "欲知春与夏，仲吕启朱明。\n蚯蚓谁教出，王菰自合生。\n帘蚕呈茧样，林鸟哺雏声。\n渐觉云峰好，徐徐带雨行。", "img": "蚯蚓 蚕茧 立夏雨"}, {"dyn": "宋", "poet": "陆游", "title": "立夏", "text": "赤帜插城扉，东君整驾归。\n泥新巢燕闹，花尽蜜蜂稀。\n槐柳阴初密，帘栊暑尚微。\n日斜汤沐罢，熟练试单衣。", "img": "燕 蜜蜂 槐树 柳树"}, {"dyn": "宋", "poet": "赵友直", "title": "立夏", "text": "四时天气促相催，一夜薰风带暑来。\n陇亩日长蒸翠麦，园林雨过熟黄梅。\n莺啼春去愁千缕，蝶恋花残恨几回。\n睡起南窗情思倦，闲看槐荫满亭台。", "img": "熏风（立夏风）立夏雨 莺 蝴蝶 槐树"}, {"dyn": "宋", "poet": "朱翌", "title": "立夏前一日登马氏山亭", "text": "忽惊夏向明朝立，便恐春从此地更。\n数蝶飞来花寂寞，乱蛙鸣处水纵横。", "img": "蝴蝶 青蛙"}, {"dyn": "宋", "poet": "杨万里", "title": "初夏即事十二解", "text": "傱教节序暗相催，历日尘生懒看来。\n却是石榴知立夏，年年此日一花开。", "img": "石榴花"}, {"dyn": "宋", "poet": "文天祥", "title": "山中立夏用坐客韵", "text": "归来泉石国，日月共溪翁。\n夏气重渊底，春光万象中。", "img": "夏气"}, {"dyn": "宋", "poet": "苏轼", "title": "阮郎归·初夏", "text": "绿槐高柳咽新蝉，薰风初入弦。\n碧纱窗下水沈烟，棋声惊昼眠。\n微雨过，小荷翻，榴花开欲然。\n玉盆纤手弄清泉，琼珠碎却圆。", "img": "槐树 柳树 蝉 熏风（立夏风）立夏雨 荷叶 石榴花"}, {"dyn": "明", "poet": "张大烈", "title": "阮郎归·立夏", "text": "绿阴铺野换新光，薰风初昼长。\n小荷贴水点横塘，蝶衣晒粉忙。\n茶鼎熟，酒卮扬，醉来诗兴狂。\n燕雏似惜落花香，双衔归画梁。", "img": "熏风（立夏风） 荷叶 蝴蝶 燕雏"}, {"dyn": "宋", "poet": "杨万里", "title": "闲居初夏午睡起", "text": "梅子留酸软齿牙，芭蕉分绿与窗纱。\n日长睡起无情思，闲看儿童捉柳花。", "img": "梅子 芭蕉 柳花"}], "stats": [], "emotion": "立夏诗词依托熏风、槐柳、石榴花、新荷、蝉等物候意象，交织着春尽夏来的复杂心绪。不少诗人在绿荫渐浓、榴花初绽的夏日景致里享受闲逸，于昼长人静的光景中体味悠然自在；春归花残、莺蝶寥落的景象，又常勾起惜春的怅惘，感慨时节流转匆促。也有诗作以平和的眼光接纳时序更替，不执着于春的逝去，静心欣赏初夏独有的清和绿意，在草木风光里安放松弛恬淡的心境。", "culture": "立夏是春夏交接的节点，蚕茧、蚯蚓出、槐阴转密、榴花开放，标志春气收束、暑气渐生，是阳气由生发走向繁茂的物候信号。此时草木由繁花转向浓荫，审美上告别春日的柔媚，转向清润沉静的初夏风貌。同时立夏关联着蚕桑、麦熟等农事，古人借这类物候体察寒暑更替，顺应季节变化调整起居，在春夏交替的风景里，完成对时序循环的感知与诗意书写。"}, {"name": "小满", "season": "夏", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·小满四月中", "text": "小满气全时，如何靡草衰。\n田家私黍稷，方伯问蚕丝。", "img": "蚕丝"}, {"dyn": "宋", "poet": "欧阳修", "title": "五绝·小满", "text": "夜莺啼绿柳，皓月醒长空。\n最爱垄头麦，迎风笑落红。", "img": "夜莺 柳树"}, {"dyn": "宋", "poet": "欧阳修", "title": "归田园四时乐春夏二首·其二", "text": "南风原头吹百草，草木丛深茅舍小。\n麦穗初齐稚子娇，桑叶正肥蚕食饱。\n老翁但喜岁年熟，饷妇安知时节好。\n野棠梨密啼晚莺，海石榴红啭山鸟。\n田家此乐知者谁？我独知之归不早。\n乞身当及强健时，顾我蹉跎已衰老。", "img": "南风（暖风）麦穗 桑叶 莺 石榴"}, {"dyn": "宋", "poet": "王之道", "title": "遣兴", "text": "久阴东虹断，小满北风寒。\n点水荷三叠，依墙竹数竿。\n乍晴何所喜，云际远山攒。", "img": "北风 荷叶 竹"}, {"dyn": "宋", "poet": "赵蕃", "title": "自桃川至辰州绝句四十有二", "text": "一春多雨慧当悭，今岁还防似去年。\n玉历检来知小满，又愁阴久碍蚕眠。", "img": "小满雨 蚕"}, {"dyn": "宋", "poet": "巩丰", "title": "晨征", "text": "静观群动亦劳哉，岂独吾为旅食催。\n鸡唱未圆天已晓，蛙鸣初散雨还来。\n清和入序殊无暑，小满先时政有雷。\n酒贱茶饶新而熟，不妨乘兴且徘徊。", "img": "鸡 蛙 雷"}, {"dyn": "元", "poet": "元淮", "title": "小满", "text": "子规声里雨如烟，润逼红绡透客毡。\n映水黄梅多半老，邻家蚕熟麦秋天。", "img": "子规 小满雨 黄梅 蚕 麦子"}, {"dyn": "明", "poet": "陶安", "title": "四月二日与黄观澜员外傅仲圭都事同访单德甫宪使不值", "text": "得闲来访单绣使，上堂只逢双墨君。\n小轩雨久长新树，近午风生驱宿云。\n更策羸骖寻雪洞，偶看稚子摘池芹。\n连营万屋无闲地，小满初晴麦气薰。", "img": "小满雨"}, {"dyn": "清", "poet": "王泰偕", "title": "吴门竹枝词四首·其四·小满", "text": "调剂阴晴作好年，麦寒豆暖两周旋。\n枇杷黄后杨梅紫，正是农家小满天。", "img": "枇杷 杨梅"}, {"dyn": "宋", "poet": "翁卷", "title": "乡村四月", "text": "绿遍山原白满川，子规声里雨如烟。\n乡村四月闲人少，才了蚕桑又插田。", "img": "子规 蚕桑"}], "stats": [], "emotion": "小满诗词以蚕、麦穗、南风、鸣鸟、小满雨等物候意象承载心绪。多数诗作立足于田家视角，写桑叶肥、蚕渐熟、麦穗初齐，满含农人期盼丰收的踏实欢喜；也有诗人置身清和初夏的乡野风光，在子规啼鸣、烟雨朦胧的景致里生出闲适徘徊的意趣。部分作品藏着顾虑与怅然，担心阴雨连绵妨害蚕眠、耽误农事，或是在田园乐景之下，感慨年华流逝、归乡迟迟，田园生机之中交织着期盼、忧思与淡淡的身世感慨。", "culture": "小满是夏初农桑关键节点，麦穗渐盈、蚕事正盛，体现阳气持续充盈、作物将熟未熟的物候特点，“小满不满” 的状态，是古人对作物生长节律细致的观察。节气紧紧绑定桑蚕与麦作两大农耕核心，蚕桑、麦收相关物象，承载着顺应天时、勤耕务本的农耕文化。审美上褪去春日柔婉，转向清和温润的初夏乡野风貌，诗人借小满物候，记录农人的劳作与祈愿，也在田园风物里安放对时序、民生的体察。"}, {"name": "芒种", "season": "夏", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·芒种五月节", "text": "芒种看今日，螳螂应节生。\n彤云高下影，鴳鸟往来声。\n渌沼莲花放，炎风暑雨情。\n相逢问蚕麦，幸得称人情。", "img": "螳螂 莲花 炎风 暑雨 蚕麦"}, {"dyn": "唐", "poet": "白居易", "title": "观刈麦", "text": "田家少闲月，五月人倍忙。\n夜来南风起，小麦覆陇黄。\n妇姑荷箪食，童稚携壶浆。\n相随饷田去，丁壮在南冈。\n足蒸暑土气，背灼炎天光。\n力尽不知热，但惜夏日长。\n复有贫妇人，抱子在其旁。\n右手秉遗穗，左臂悬敝筐。\n听其相顾言，闻者为悲伤。\n家田输税尽，拾此充饥肠。\n今我何功德，曾不事农桑。\n吏禄三百石，岁晏有余粮。\n念此私自愧，尽日不能忘。", "img": "小麦"}, {"dyn": "唐", "poet": "窦常", "title": "北固晚眺", "text": "水国芒种后，梅天风雨凉。\n露蚕开晚簇，江燕绕危樯。\n山趾北来固，潮头西去长。\n年年此登眺，人事几销亡。", "img": "蚕"}, {"dyn": "宋", "poet": "陆游", "title": "时雨", "text": "时雨及芒种，四野皆插秧。\n家家麦饭美，处处菱歌长。\n老我成惰农，永日付竹床。\n衰发短不栉，爱此一雨凉。\n庭木集奇声，架藤发幽香。\n莺衣湿不去，劝我持一觞。\n即今幸无事，际海皆农桑。\n野老固不穷，击壤歌虞唐。", "img": "秧 麦"}, {"dyn": "宋", "poet": "范成大", "title": "芒种后积雨骤冷三绝（其三）", "text": "梅霖倾泻九河翻，百渎交流海面宽。\n良苦吴农田下湿，年年披絮插秧寒。", "img": "秧"}, {"dyn": "宋", "poet": "楼璹", "title": "耕图二十一首·拔秧", "text": "新秧初出水，渺渺翠毯齐。\n清晨且拔擢，父子争提携。\n既沐青满握，再栉根无泥。\n及时趁芒种，散著畦东西。", "img": "秧 泥"}, {"dyn": "宋", "poet": "韩淲", "title": "芒种（其一）", "text": "田家一雨插秧时，成把担禾水拍泥。\n分段排行到畦岸，背蓬浑不管归迟。", "img": "秧 畦岸"}, {"dyn": "元", "poet": "赵孟頫", "title": "题耕织图二十四首奉懿旨撰·耕·其五（五月）", "text": "仲夏苦雨乾，二麦先后熟。\n南风吹陇亩，惠气散清淑。\n是为农夫庆，所望实其腹。\n沽酒醉比邻，语笑声满屋。\n纷然收获罢，高廪起相属。\n有周成王业，后稷播百谷。\n皇天贻来牟，长世自兹卜。\n愿言仍岁稔，四海尽蒙福。", "img": "雨 麦 百谷"}, {"dyn": "明", "poet": "樊阜", "title": "田间杂咏六首（其六）", "text": "枣花落靡靡，一犬护柴关。\n节序届芒种，何人得幽闲。\n蛙鸣池水满，细草生阶间。\n刈麦欲终亩，风吹雨过山。\n大儿早未饭，叹息农事艰。\n豪贵本天命，悠悠不可攀。", "img": "枣花 蛙 麦"}, {"dyn": "明", "poet": "汤珍", "title": "石桥", "text": "僧笠归花外，渔舟系柳边。\n村村逐芒种，播谷满菑田。", "img": "谷 田"}, {"dyn": "明", "poet": "区怀年", "title": "咏荔枝（其一）", "text": "芒种家家听子规，邀欢何处柳塘西。\n香风十里嘘长夏，万簇红云酿火齐。", "img": "子规"}, {"dyn": "明", "poet": "屠侨", "title": "五月梅雨", "text": "才见迎梅又送梅，榴花五月雨中开。\n江南芒种田家候，白下端阳客子杯。\n古壁腥延蜗角上，空阶青引石衣来。\n离肠何苦淹淹滴，用愧当年济旱才。", "img": "榴花"}, {"dyn": "清", "poet": "玄烨（康熙）", "title": "题耕图二十三首·其九", "text": "青葱刺水满平川，移植西畴更勃然。\n节序惊心芒种迫，分秧须及夏初天。", "img": "秧"}, {"dyn": "清", "poet": "胤禛（雍正）", "title": "插秧", "text": "物候当芒种，农人戒插田。\n倏分行整整，入望影芊芊。\n白柳花争陌，黄梅子熟天。\n一朝千顷遍，长日正如年。", "img": "田 白柳花 黄梅子"}, {"dyn": "清", "poet": "洪亮吉", "title": "伊犁记事诗", "text": "芒种才过雪不霁，伊犁河外草初肥。\n生驹步步行难稳，恐有蛇从鼻观飞。", "img": "草 蛇"}], "stats": [], "emotion": "芒种诗词以麦黄、新秧、蚕麦、梅雨、炎风为物候底色，情感伴随着农时节奏起伏。南风起处，小麦覆陇，四野插秧、担禾拍泥，“分秧须及夏初天” 的紧迫与 “足蒸暑土气，背灼炎天光” 的燥热交织，使劳作的艰辛成为基调；而麦饭飘香、菱歌互答、沽酒醉邻、语笑满屋，又把丰稔之喜写得踏实可亲，“相逢问蚕麦，幸得称人情” 把这份喜悦化作邻里的一句问候。苦与喜相互映照：一边是贫妇拾穗、“念此私自愧” 的自责与 “豪贵本天命” 的无力，一边则是击壤歌唐、际海农桑的太平想象；节序更替又牵动出 “人事几销亡” 的怅惘与 “迎梅送梅” 的漂泊之感。忙碌与欣慰、悯农与自愧、乡愁与清欢彼此叠加，构成芒种独有的复杂情感。", "culture": "芒种处在仲夏之初，麦熟秧青、梅雨初盛是其标志性物候，“芒” 指麦芒，“种” 指播种，节气之名本身就代表农事节律：收麦与插秧同时进行，形成一年中最吃紧的 “一收一种” 转换。芒种的诗中运用物候时承袭月令，螳螂生、鵙始鸣见于《礼记・月令》，元稹 “螳螂应节生” 便以物候作为节令到来的凭据；蚕与麦并称，“相逢问蚕麦” 承载蚕桑与麦作两种生计记忆；后稷播百谷、愿四海蒙福，则把丰收系于农神天命与德政，农事丰足被视作世道清明的证据。江南此时与梅雨同期，黄梅子熟、梅霖倾泻形成独特的 “湿” 的书写，枣花落、榴花雨中开又逢花事将尽与端午相邻。农时之紧迫、重农之伦理与惜春之审美相融，使芒种成为连通自然时序、农耕生计与家国秩序的特殊节气。"}, {"name": "夏至", "season": "夏", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·夏至五月中", "text": "处处闻蝉响，须知五月中。\n龙潜渌水穴，火助太阳宫。\n过雨频飞电，行云屡带虹。\n蕤宾移去后，二气各西东。", "img": "蝉 雨 飞电(雷) 虹"}, {"dyn": "唐", "poet": "韦应物", "title": "夏至避暑北池", "text": "昼晷已云极，宵漏自此长。\n未及施政教，所忧变炎凉。\n公门日多暇，是月农稍忙。\n高居念田里，苦热安可当。\n亭午息群物，独游爱方塘。\n门闭阴寂寂，城高树苍苍。\n绿筠尚含粉，圆荷始散芳。\n于焉洒烦抱，可以对华觞。", "img": "绿筠(竹子) 圆荷"}, {"dyn": "唐", "poet": "白居易", "title": "和梦得夏至忆苏州呈卢宾客", "text": "忆在苏州日，常谙夏至筵。\n粽香筒竹嫩，炙脆子鹅鲜。\n水国多台榭，吴风尚管弦。\n每家皆有酒，无处不过船。\n交印君相次，褰帷我在前。\n此乡俱老矣，东望共依然。\n洛下麦秋月，江南梅雨天。\n齐云楼上事，已上十三年。", "img": "竹 鹅 梅雨"}, {"dyn": "宋", "poet": "张耒", "title": "夏至", "text": "长养功已极，大运忽云迁。\n人间漫未知，微阴生九原。\n杀生忽更柄，寒暑将成年。\n崔巍干云树，安得保芳鲜。\n几微物所忽，渐进理必然。\n韪哉观化子，默坐付忘言。", "img": "云"}, {"dyn": "宋", "poet": "陈与义", "title": "夏至日与太学同舍会葆真二首（其一）", "text": "微官有阀阅，三赋池上诗。\n林密知夏深，仰看天离离。\n官忙负远兴，觞至及良时。\n荷气夜来雨，百鸟清昼迟。\n微风不动苹，坐看水色移。\n门前争夺场，取欢不偿悲。\n欲归未得去，日暮多黄鹂。", "img": "雨 百鸟 黄鹂"}, {"dyn": "宋", "poet": "杨万里", "title": "和昌英叔夏至喜雨", "text": "清酣暑雨不缘求，犹似梅黄麦欲秋。\n去岁如今禾半死，吾曹遍祷汗交流。\n此生未用愠三已，一饱便应哦四休。\n花外绿畦深没鹤，来看莫惜下邳侯。", "img": "暑雨 黄梅"}, {"dyn": "宋", "poet": "范成大", "title": "夏至", "text": "李核垂腰祝饐，粽丝系臂扶羸。\n节物竞随乡俗，老翁闲伴儿嬉。", "img": "粽丝"}, {"dyn": "元", "poet": "周权", "title": "夏至", "text": "昼刻已长漏迟迟，榴花照屋蜀葵滋。\n南风不断黄梅雨，正是田家刈麦时。", "img": "榴花 黄梅雨"}, {"dyn": "元", "poet": "许有壬", "title": "夏至", "text": "昼永漏声迟，阴生暑气滋。\n荷香浮曲沼，蝉响出高枝。", "img": "荷 蝉"}, {"dyn": "元", "poet": "徐贲", "title": "夏至日北涧自留坐怀一二知己", "text": "日午步屧去，行循北涧浔。\n解衣因坐久，对此嘉树林。\n虽无薰风至，微凉满芳阴。\n况兹涧中水，汪然澄我心。\n白鸥自荡漾，黄鸟有好音。\n我有一樽酒，欲酌还停斟。\n安得携朋俦，于焉共清吟。", "img": "白鸥 黄鸟(黄鹂)"}, {"dyn": "明", "poet": "刘基", "title": "夏日杂兴", "text": "夏至阴生景渐催，百年已半亦堪哀。\n葺鳞不入龙螭梦，铩羽何劳燕雀猜。\n雨砌蝉花粘碧草，风檐萤火出苍苔。\n细观景物宜消遣，寥落兼无浊酒杯。", "img": "蝉 萤火(萤火虫)"}, {"dyn": "明", "poet": "吴与弼", "title": "夏至", "text": "昼雨聊城逢夏至，暮云江右忆侬家。\n东林新箨知成荫，南亩香粳想俵花。", "img": "新箨(新竹) 香粳(米)"}, {"dyn": "清", "poet": "彭孙遹", "title": "卜算子·夏至日", "text": "才过困人天，又把黄梅做。\n试捲疏帘一倚阑，小雨吹红酢。\n草草百年身，悔杀从前错。\n来日还如去日长，没个安排处。", "img": "黄梅"}, {"dyn": "清", "poet": "弘历（乾隆）", "title": "夏至进宫斋戒舟过万泉庄", "text": "浮云遮晓日，宿雨涤遥山。\n柳色烟千缕，蝉声水一湾。\n良苗欣沃濯，新涨听潺湲。\n命驾缘临祭，维舟岂趁闲。\n慰怀惟谷宝，触景忆民艰。\n弥月忧心切，今来略解颜。", "img": "浮云 蝉"}, {"dyn": "清", "poet": "厉鹗", "title": "夏至日同友人湖上", "text": "湖光收雨气，节序报长赢。\n荷嫩香初浅，蝉疏响未盈。", "img": "荷 蝉"}], "stats": [], "emotion": "夏至诗词以蝉鸣、飞电、虹霓、圆荷、绿竹、梅雨为物候底色，情感在昼长暑盛中显出忙与闲、静与倦的交错。“昼晷已云极，宵漏自此长”“亭午息群物，独游爱方塘”，长日难消，人于是退向池上林阴；绿筠含粉、圆荷散芳、荷香浮沼、涧水微凉，避暑的清欢由此而生，却常伴着 “欲酌还停斟”“安得携朋俦” 的孤寂，闲适里透出无人共饮的寥落。另一面是暑热之下的民生牵念：“公门日多暇，是月农稍忙”“高居念田里，苦热安可当”，以及 “去岁如今禾半死，吾曹遍祷汗交流” 的祈雨忧旱。而夏至筵上粽香鹅鲜、吴风管弦、每家皆有酒，粽丝系臂、老翁伴儿嬉，又见节俗的热闹与稚趣。热与凉、忙与闲、欢宴与迟暮（“百年已半亦堪哀”）、客居与怀乡（“暮云江右忆侬家”）层层叠压，构成夏至独有的复杂情感。", "culture": "夏至处在仲夏之中，蝉响、雷电、虹霓、圆荷、新竹是标志性物候，阳气至此而极、阴气自此而生，“蕤宾移去后，二气各西东”“微阴生九原” 正是阴阳消长的律历表达，昼晷极而宵漏长，这一节气的天文学意味最为直露。它同时是民俗的节点：夏至筵上粽香筒竹、炙脆子鹅、吴风管弦、家家有酒，粽丝系臂以扶羸、李核祝饐以祈健，“节物竞随乡俗” 说明唐宋夏至一如节庆，饮食、祈健与宴游并行。农事上则见地域之别，“洛下麦秋月，江南梅雨天”“南风不断黄梅雨，正是田家刈麦时”，麦秋与梅雨同期而至，收与种在湿热中交接。物候之盛与阴生之微相衬，节俗之欢与农事之忧并存，使夏至成为连通天时阴阳、乡俗礼宴与农桑生计的特殊节气。"}, {"name": "小暑", "season": "夏", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·小暑六月节", "text": "倏忽温风至，因循小暑来。\n竹喧先觉雨，山暗已闻雷。\n户牖深青霭，阶庭长绿苔。\n鹰鹯新习学，蟋蟀莫相催。", "img": "雨 雷 绿苔 蟋蟀"}, {"dyn": "唐", "poet": "武元衡", "title": "夏日对雨寄朱放拾遗", "text": "才非谷永传，无意谒王侯。\n小暑金将伏，微凉麦正秋。\n远山欹枕见，暮雨闭门愁。\n更忆东林寺，诗家第一流。", "img": "麦 暮雨"}, {"dyn": "唐", "poet": "孟浩然", "title": "夏日南亭怀辛大", "text": "山光忽西落，池月渐东上。\n散发乘夕凉，开轩卧闲敞。\n荷风送香气，竹露滴清响。\n欲取鸣琴弹，恨无知音赏。\n感此怀故人，中宵劳梦想。", "img": "荷 竹"}, {"dyn": "宋", "poet": "秦观", "title": "纳凉", "text": "携杖来追柳外凉，画桥南畔倚胡床。\n月明船笛参差起，风定池莲自在香。", "img": "柳 池莲"}, {"dyn": "宋", "poet": "杨万里", "title": "夏夜追凉", "text": "夜热依然午热同，开门小立月明中。\n竹深树密虫鸣处，时有微凉不是风。", "img": "竹 虫"}, {"dyn": "宋", "poet": "韩淲", "title": "十八日小暑大雨", "text": "申祷山川便作霖，耘苗时候想田深。\n且欣小暑能如此，更愿新秋得似今。\n早稻欲花将就实，晚禾成叶未抽心。\n天应不忍焦劳意，直自初栽已望阴。", "img": "早稻 晚禾"}, {"dyn": "元", "poet": "方回", "title": "夜望", "text": "夕阳已下月初生，小暑才交雨渐晴。\n南北斗杓双向直，乾坤卦位八方明。\n古人已往言犹在，末俗何为路未平。\n似觉草虫亦多事，为予凄楚和吟声。", "img": "草虫"}, {"dyn": "明", "poet": "易震吉", "title": "小暑", "text": "小暑啜瓜瓤。粗葛衣裳。\n炎蒸窗牖气初刚。无计遣兹长昼也，\n茗碗炉香。\n\n深院一垂杨。又闹鸣螀。\n簿书堆案使人忙。何不归与湖水上，\n做个渔郎。", "img": "瓜 垂杨"}, {"dyn": "明", "poet": "朱高炽", "title": "池亭纳凉", "text": "雨滋槐叶翠，风过藕花香。\n舞燕来青琐，流莺出建章。", "img": "槐叶 藕花 燕 莺"}, {"dyn": "清", "poet": "乔远炳", "title": "夏日", "text": "薰风愠解引新凉，小暑神清夏日长。\n断续蝉声传远树，呢喃燕语倚雕梁。\n眠摊薤簟千纹滑，座接花茵一院香。\n雪藕冰桃情自适，无烦珍重碧筒尝。", "img": "蝉 燕 雪藕 冰桃"}, {"dyn": "清", "poet": "阮元", "title": "小暑节赏菊", "text": "棉衣颇耐午阴凉，瓦盎花开老菊黄。\n不是石栏红菡萏，错将小暑认重阳。", "img": "菊"}, {"dyn": "清", "poet": "玄烨（康熙）", "title": "石匣营作", "text": "青岭横峰荫薜萝，时方小暑绿新荷。\n蒲编诗兴光岩穴，虎士桓桓扣角歌。", "img": "荷 蒲"}], "stats": [], "emotion": "小暑诗词以温风、雷雨、绿苔、荷竹、蝉声、瓜藕为物候底色，情感多在暑热中转向对 “凉” 的寻觅。“竹喧先觉雨，山暗已闻雷”“夜热依然午热同”，暑气初刚而昼夜难消，人于是携杖追凉、散发乘夕、开门小立，“时有微凉不是风” 写尽长昼里一点稀薄的舒解；荷风送香、竹露滴响、雪藕冰桃、啜瓜焚香、薤簟花茵，纳凉之乐具体而日常。但凉意往往引出孤怀：“欲取鸣琴弹，恨无知音赏”“暮雨闭门愁”“无意谒王侯” 的疏离、“簿书堆案使人忙，何不归与湖水上” 的倦怠，闲适之下压着无人共语的寂寞。另一路是农事之忧，“申祷山川便作霖”“早稻欲花将就实，晚禾成叶未抽心”，盼雨的焦灼与盼熟的期待同时出现；而 “错将小暑认重阳” 的时序错觉、“草虫多事和吟声” 的凄楚，又添一层若有若无的怅然。静与闷、闲与孤、纳凉之乐与忧旱之心交织，构成小暑独有的复杂情感。", "culture": "小暑处在季夏之初，温风、雷雨、绿苔、新荷、蝉燕是标志性物候，小暑三候为温风至、蟋蟀居壁、鹰始鸷，元稹 “倏忽温风至”“鹰鹯新习学，蟋蟀莫相催” 把月令物候逐条写进诗里，蟋蟀之 “催” 已含向秋推移的预感。“金将伏” 一句点出三伏将起，暑气至此而刚，消暑于是成为一整套生活方式：啜瓜瓤、食雪藕冰桃、着粗葛、卧薤簟、倚胡床、茗碗炉香、画桥船笛，饮食、器物与居处共同构成夏日养生的日常审美。诗中还保留节气与天象卦气的对应，“南北斗杓双向直，乾坤卦位八方明” 以斗建与卦位标记时令；农事上 “微凉麦正秋”“早稻欲花将就实，晚禾成叶未抽心”，正见双季稻区抢时望熟的两条线。暑热之盛与觅凉之趣相衬，农桑之忧与出处之思并存，使小暑成为连通时令物候、消暑生活与士人隐逸情怀的特殊节气。"}, {"name": "大暑", "season": "夏", "poems": [{"dyn": "唐", "poet": "王维", "title": "苦热", "text": "赤日满天地，火云成山岳。\n草木尽焦卷，川泽皆竭涸。\n轻纨觉衣重，密树苦阴薄。\n莞簟不可近，絺绤再三濯。\n思出宇宙外，旷然在寥廓。\n长风万里来，江海荡烦浊。\n却顾身为患，始知心未觉。\n忽入甘露门，宛然清凉乐。", "img": "赤日"}, {"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·大暑六月中", "text": "大暑三秋近，林钟九夏移。\n桂轮开子夜，萤火照空时。\n菰果邀儒客，菰蒲长墨池。\n绛纱浑卷上，经史待风吹。", "img": "萤火 菰果 菰蒲"}, {"dyn": "宋", "poet": "曾几", "title": "大暑", "text": "赤日几时过，清风无处寻。\n经书聊枕籍，瓜李漫浮沉。\n兰若静复静，茅茨深又深。\n炎蒸乃如许，那更惜分阴。", "img": "瓜"}, {"dyn": "宋", "poet": "司马光", "title": "六月十八日夜大暑", "text": "老柳蜩螗噪，荒庭熠燿流。\n人情正苦暑，物怎已惊秋。\n月下濯寒水，风前梳白头。\n如何夜半客，束带谒公侯。", "img": "老柳 蜩螗"}, {"dyn": "明", "poet": "程敏政", "title": "六月二十二日大暑坐墙西槐树下有作", "text": "门外炎光炽，墙西一径开。\n残阳馀古瓦，凉吹发高槐。\n鸟与人俱乐，诗随景自来。\n无因堪破寂，童子进冰梅。", "img": "高槐 冰梅"}, {"dyn": "明", "poet": "文徵明", "title": "古树茅堂图（题画）", "text": "永夏茅堂风日嘉，凉阴寂历树交加。\n客来解带围新竹，燕起冲帘落晚花。\n领略清言苍玉麈，破除沉困紫团茶。\n六街车马尘如海，不到柴桑处士家。", "img": "新竹 燕"}, {"dyn": "清", "poet": "袁枚", "title": "三伏", "text": "炎帝代辞客，幽人得自如。\n门无朱鬣马，家有白云车。\n雨久荷花密，风高杨柳疏。\n年年三伏日，添著几行书。", "img": "荷花 杨柳"}, {"dyn": "清", "poet": "南龙翼", "title": "大暑日偶吟", "text": "归卧穷山一秃翁，旧游踪迹转头空。\n黄莺已老玄蝉唳，白雨初收赤日烘。\n午馐才依南亩草，朝酣尚引北窗风。\n清秋节候何时至，大暑方当六月中。", "img": "黄莺 蝉 赤日"}], "stats": [], "emotion": "大暑诗词以赤日、火云、焦卷草木、蜩螗、萤火、瓜李冰梅为物候底色，情感先被推到极热的一端。热到极处后，诗中通常有两种排解方式：一是向外寻求凉意，把瓜李浸在水中，让童子送上冰梅，拂过高槐下的凉风，用冷水洗濯身体、梳理白发，或者围坐新竹旁解开衣带，“鸟与人俱乐，诗随景自来”；二是向内寻求解脱，如 “思出宇宙外，旷然在寥廓”“忽入甘露门，宛然清凉乐”，把身体所受的煎熬转化为内心的澄定。但热的顶点已含秋意，“大暑三秋近”“物怎已惊秋”“清秋节候何时至”，苦暑之中先起盼秋之心；而 “六街车马尘如海，不到柴桑处士家”“如何夜半客，束带谒公侯” 的对照，又把天气的炎凉写成世情的炎凉。躁与静、热恼与清凉、盼秋与叹世交织，构成大暑独有的复杂情感。", "culture": "大暑处在季夏之中，赤日、火云、焦草、蜩螗、萤火、菰蒲是标志性物候，此时三伏正盛、湿热交蒸，“大暑三秋近，林钟九夏移” 以林钟之律与三秋之近标出节令位置，“年年三伏日” 点明伏日制度与节气的叠合。消暑在诗里已成成套的生活方式：瓜李浮于寒泉、童子进冰梅、紫团茶破沉困、濯寒水梳白头、解带围新竹，饮食、器物与居处共同承担驱暑的功能；而 “经书聊枕籍”“经史待风吹”“年年三伏日，添著几行书” 更见士人以读书消长夏的传统，三伏遂由天时转为文人的闲居节奏。诗中还留下由热入禅的思理，“却顾身为患，始知心未觉”“忽入甘露门，宛然清凉乐”，把身体的苦热当作心性修行的入口；“柴桑处士”“幽人自如” 与 “六街车马尘如海” 的对举，则让大暑成为检验出处之志的节气。物候之烈、伏日之制与心性之思相融，使大暑成为连通自然极热、日常消暑与士人修养的特殊节气。"}, {"name": "立秋", "season": "秋", "poems": [{"dyn": "唐", "poet": "刘言史", "title": "立秋", "text": "兹晨戒流火，商飙早已惊。\n云天收夏色，木叶动秋声。", "img": "云天 木叶"}, {"dyn": "唐", "poet": "白居易", "title": "立秋夕有怀梦得", "text": "露簟荻竹清，风扇蒲葵轻。\n一与故人别，再见新蝉鸣。\n是夕凉飙起，闲境入幽情。\n回灯见栖鹤，隔竹闻吹笙。\n夜茶一两杓，秋吟三数声。\n所思渺千里，云外长洲城。", "img": "蝉 蒲葵 栖鹤"}, {"dyn": "宋", "poet": "刘翰", "title": "立秋", "text": "乳鸦啼散玉屏空，一枕新凉一扇风。\n睡起秋声无觅处，满阶梧桐月明中。", "img": "乳鸦 梧桐"}, {"dyn": "宋", "poet": "杨万里", "title": "六月十三日立秋", "text": "暑中剩喜立秋初，特地西风半点无。\n旋汲井花浇睡眼，洒将荷叶看跳珠。", "img": "荷叶"}, {"dyn": "元", "poet": "方回", "title": "立秋", "text": "暑赦如闻降德音，一凉欢喜万人心。\n虽然未便梧桐落，终是相将蟋蟀吟。\n初夜银河正牛女，诘朝红日尾觜参。\n朝廷欲觅玄真子，蟹舍渔蓑烟雨深。", "img": "梧桐 蟋蟀"}, {"dyn": "元", "poet": "周权", "title": "立秋日晚坐", "text": "山云漠漠树苍苍，风荐池荷满意香。\n独据绳床眠未得，一檐风雨夜初凉。", "img": "池荷"}, {"dyn": "明", "poet": "李梦阳", "title": "乙亥立秋", "text": "今日秋风起，连年湿病苏。\n应时微雨歇，侵晓断云徂。\n已复寒蝉集，空嗟蕙草孤。\n步檐惊骤健，一叶下庭梧。", "img": "蝉 蕙草"}, {"dyn": "清", "poet": "弘历（乾隆）", "title": "立秋日作", "text": "已识山中早晚凉，今朝况复立秋当。\n如何午热为孤注，疑是金官让末光。\n桐叶庭边想影落，草虫砌下觉声扬。\n农占晴雨纷如讼，历验原来亦鲜偿。", "img": "桐叶 草虫"}, {"dyn": "清", "poet": "纳兰性德", "title": "木兰花慢·立秋夜雨送梁汾南行", "text": "盼银河迢递，惊入夜，\n转清商。乍西园蝴蝶，\n轻翻麝粉，暗惹蜂黄。\n炎凉。等闲瞥眼，\n甚丝丝、点点搅柔肠。应是登临送客，\n别离滋味重尝。\n\n疑将。水墨画疏窗，\n孤影淡潇湘。倩一叶高梧，\n半条残烛、做尽商量。荷裳。\n被风暗剪，问今宵、谁与盖鸳鸯。\n从此羁愁万叠，梦回分付啼螀。", "img": "高梧(梧桐)  荷"}], "stats": [], "emotion": "立秋诗词以云天、木叶、梧桐、新蝉、蒲葵、池荷为物候底色，情感的核心是对 “初变” 的敏锐捕捉。“一叶下庭梧”“满阶梧桐月明中”，秋并不以温度到来，而是先现于云的收束、叶的声响与月下的影，诗人几乎都在同一瞬间被这细微的转换击中。与这敏感相伴的是喜凉之心：“一凉欢喜万人心” 如闻暑赦。可立秋常常名不副实，“特地西风半点无”“午热为孤注”，秋已至而热未退，情感便悬在等待里。凉风一起，又最易牵动别离与羁愁，“一与故人别，再见新蝉鸣”“所思渺千里”“从此羁愁万叠，梦回分付啼螀”，商声入耳即是离声。而回灯见鹤、隔竹闻笙、夜茶数杓、秋吟三两声、独据绳床听一檐风雨，又在静夜中留出一段清欢。喜凉与余热、静美与羁愁相互缠绕，构成立秋独有的复杂情感。", "culture": "立秋处在孟秋之始，云天、木叶、梧桐、新蝉、寒蝉是标志性物候，立秋三候为凉风至、白露降、寒蝉鸣，诗中的 “凉飙起”“已复寒蝉集” 正是候应的直写。“兹晨戒流火，商飙早已惊” 以大火西流与商声起为秋之信，“疑是金官让末光” 则以五行秋官之说解释午热未尽，天文、乐律与五行知识在这里共同标记节令。梧桐报秋是最具象征的一环，“虽然未便梧桐落”“桐叶庭边想影落”“一叶下庭梧”，一叶之落被当作天下之秋的先声，节气的抽象由此落实为一片叶子。立秋又与七夕相接，“初夜银河正牛女” 把节气纳入星象与七夕传说；“农占晴雨纷如讼，历验原来亦鲜偿” 则记下农谚占验的风俗与其失效，可见节气知识在民间运作中的另一面。物候之微、律历之辨与离别之思相融，使立秋成为连通自然转折、农事占验与文人悲秋传统的特殊节气。"}, {"name": "处暑", "season": "秋", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·处暑七月中", "text": "向来鹰祭鸟，渐觉白藏深。\n叶下空惊吹，天高不见心。\n气收禾黍熟，风静草虫吟。\n缓酌樽中酒，容调膝上琴。", "img": "禾黍 草虫"}, {"dyn": "唐", "poet": "白居易", "title": "早秋曲江感怀", "text": "离离暑云散，袅袅凉风起。\n池上秋又来，荷花半成子。\n朱颜易销歇，白日无穷已。\n人寿不如山，年光急于水。\n青芜与红蓼，岁岁秋相似。\n去岁此悲秋，今秋复来此。", "img": "凉风 荷花 青芜(杂草) 红蓼"}, {"dyn": "宋", "poet": "苏泂", "title": "长江二首（其二）", "text": "处暑无三日，新凉直万金。\n白头更世事，青草印禅心。\n放鹤婆娑舞，听蛩断续吟。\n极知仁者寿，未必海之深。", "img": "青草"}, {"dyn": "宋", "poet": "吕本中", "title": "处暑", "text": "平时遇处暑，庭户有余凉。\n乙纪走南国，炎天非故乡。\n寥寥秋尚远，杳杳夜光长。\n尚可留连否，年丰粳稻香。", "img": "粳稻"}, {"dyn": "宋", "poet": "张嵲", "title": "七月二十四日山中已寒二十九日处暑", "text": "尘世未徂暑，山中今授衣。\n露蝉声渐咽，秋日景初微。\n四海犹多垒，余生久息机。\n漂流空老大，万事与心违。", "img": "蝉"}, {"dyn": "元", "poet": "宋褧", "title": "七月三日喜至郧县山行兼旬至此始出", "text": "稻花香里过琳宫，一舸斜阳汉水东。\n下马已辞山巀嶪，开轩仍见竹葱茏。\n画檐不碍迎霜叶，玉宇频来处暑风。\n童御无知友朋远，满襟幽思与谁同。", "img": "稻花 处暑风"}, {"dyn": "元", "poet": "方回", "title": "暑退", "text": "逆旅朝难夕，更生暑忽凉。\n自能捐嗜欲，足可看奔忙。\n即恐来鸿雁，翻成畏雪霜。\n去年几人健，同与嗅秋香。", "img": "鸿雁"}, {"dyn": "清", "poet": "来集之", "title": "洞仙歌·赠仁和令张玉甲", "text": "湖光可掬。正秋光澄绿。\n折得荷花香不俗。更西风吹满、万亩黄云，\n刚处暑，共报田家雨足。\n此邦真乐土，烽火无惊，\n时见啼禽在修竹。试问涌金门外、月如何，\n七夕后、银河先复。把公事、湖中尽完来，\n用汝作盐梅、调羹黄屋。", "img": "荷花 竹"}], "stats": [], "emotion": "处暑诗词以禾黍、草虫、凉风、荷花、青芜红蓼、鸿雁为物候底色，情感的第一反应是 “得凉” 之喜。“处暑无三日，新凉直万金”“庭户有余凉”，凉在此时节被当作可以标价的东西来珍惜；暑气一退，身体先松下来，于是有 “缓酌樽中酒，容调膝上琴” 的从容，有放鹤舞、听蛩吟、青草印禅心的安静。可凉意一到，时间感便随之逼来：“朱颜易销歇，白日无穷已”“人寿不如山，年光急于水”“白头更世事”“漂流空老大，万事与心违”，处暑几乎是全组中最易引出迟暮之叹的节气，因为热退得清楚，人老得也清楚。诗中另有一种循环的惘然，“青芜与红蓼，岁岁秋相似”，景物年年如旧，而 “去岁此悲秋，今秋复来此”；客居者则写 “炎天非故乡”“逆旅朝难夕”，旅思与 “即恐来鸿雁，翻成畏雪霜” 的紧迫叠在一处。而 “万亩黄云，刚处暑，共报田家雨足”“稻花香里”“年丰粳稻香” 又给这一节气留出丰收的踏实与乐土的安慰。得凉、叹老、旅思与丰年之喜交织，构成处暑独有的复杂情感。", "culture": "处暑处在孟秋之末、三伏将尽之时，禾黍、草虫、凉风、残荷、青芜红蓼是标志性物候，三候为鹰乃祭鸟、天地始肃、禾乃登，“向来鹰祭鸟”“气收禾黍熟” 两联几乎把候应逐条写尽，秋至此才真正 “收”。诗中 “渐觉白藏深” 用《尔雅》“秋为白藏” 的古称，“山中今授衣” 则接《豳风・七月》的衣候传统，节气由是同时是物候、衣候与农候的刻度。秋收是这一节气的实处：禾黍熟、粳稻香、稻花满路、“万亩黄云” 共报雨足，禾乃登之 “登” 在诗里成了可闻可见的香气与颜色。物候细节也很讲究，“荷花半成子” 写夏物结子而未谢，“露蝉声渐咽” 写蝉声收束，都是退场之际的准确记录。士人则把它当作转身的时机，“自能捐嗜欲”“余生久息机”“青草印禅心”，又有 “四海犹多垒” 的忧世与 “烽火无惊” 的祝愿，令这一节气兼有收成之喜与出处之思。物候之收、农事之登与士人之思相融，使处暑成为连通自然退暑、秋收时序与人生迟暮感的特殊节气。"}, {"name": "白露", "season": "秋", "poems": [{"dyn": "唐", "poet": "杜甫", "title": "月夜忆舍弟", "text": "戍鼓断人行，边秋一雁声。\n露从今夜白，月是故乡明。\n有弟皆分散，无家问死生。\n寄书长不达，况乃未休兵。", "img": "雁 露"}, {"dyn": "唐", "poet": "白居易", "title": "南湖晚秋", "text": "八月白露降，湖中水方老。\n旦夕秋风多，衰荷半倾倒。\n手攀青枫树，足踏黄芦草。\n惨澹老容颜，冷落秋怀抱。\n有兄在淮楚，有弟在蜀道。\n万里何时来，烟波白浩浩。", "img": "白露 秋风 黄芦草"}, {"dyn": "宋", "poet": "仲殊", "title": "南柯子·忆旧", "text": "十里青山远，潮平路带沙。\n数声啼鸟怨年华。又是凄凉时候，\n在天涯。白露收残月，\n清风散晓霞。绿杨堤畔问荷花：\n记得年时沽酒，那人家？", "img": "白露 绿杨 荷花"}, {"dyn": "元", "poet": "仇远", "title": "秋感", "text": "明朝交白露，此夜起金风。\n灯下倚孤枕，篱根语百虫。\n梧桐何处落，杼轴几家空。\n客意惊秋半，炎凉信转蓬。", "img": "白露 梧桐"}, {"dyn": "元", "poet": "张翥", "title": "闰中秋，是日白露节", "text": "河汉云消溢素光，重开樽酒据绳床。\n嫦娥斟酒犹前夕，老子婆娑且醉乡。\n风信两番生绿桂，年华一寸入黄杨。\n怪来诗思清难忍，早雁声中露欲霜。", "img": "绿桂 黄杨"}, {"dyn": "元", "poet": "刘因", "title": "秋莲", "text": "瘦影亭亭不自容，淡香杳杳欲谁通。\n不堪翠减红销际，更在江清月冷中。\n拟欲青房全晚节，岂知白露已秋风。\n盛衰老眼依然在，莫放扁舟酒易空。", "img": "白露 秋风"}, {"dyn": "元", "poet": "赵孟頫", "title": "题耕织图二十四首奉懿旨撰·耕·其八（八月）", "text": "白露下百草，茎叶日纷委。\n是时禾黍登，充积遍都鄙。\n在郊既千庾，入邑复万轨。\n人言田家乐，此乐谁可比。\n租赋以输官，所馀足储峙。\n不然风雪至，冻馁及妻子。\n优游茅檐下，庶可以卒岁。\n太平元有象，治世乃如此。", "img": "白露 草"}, {"dyn": "明", "poet": "高棅", "title": "衡江夕露", "text": "大江白露下，秋气横沧浪。\n夜色不映水，微风忽吹裳。\n孤舟待明月，时闻兰杜香。", "img": "秋气 明月"}, {"dyn": "明", "poet": "顾璘", "title": "白露", "text": "白露凄凄，原草具腓。\n日月于迈，载授我衣。\n北山有堂，江注其麓。\n薄言出游，以写心曲。\n山木斓斑，江云差池。\n乐以旨酒，委蛇委蛇。\n尔樵尔渔，来往无怒。\n尔农获斯，黍稷如岵。\n戋戋守臣，实蹈百愆。\n何以逭之，曰维丰年。\n丰年伊何，维民之德。\n民之颂之，天子之泽。", "img": "白露 腓草(衰草)"}, {"dyn": "清", "poet": "魏裔介", "title": "雨中吟", "text": "昔日谈王霸，今朝学圃农。\n鸡豚时自牧，饮啄与人同。\n痛哭空怀古，狂歌拟送穷。\n夜来白露至，已满菊花丛。", "img": "白露 菊花"}, {"dyn": "清", "poet": "奕绘", "title": "长相思·其二", "text": "一峰秋，万峰秋。\n白露为霜草树秋。西风刮面秋。\n\n寓园秋，故园秋。\n学道论文三十秋。浮生知几秋！", "img": "白露 草 树 西风"}, {"dyn": "清", "poet": "查慎行", "title": "二十七日发热河", "text": "耿耿疏星晓，泠泠白露秋。\n老松经烧断，顽石隘溪流。\n草苫沿篱屋，人骑渡水牛。\n塞田霜气晚，七月已全收。", "img": "白露 老松"}], "stats": [], "emotion": "白露诗词以白露、雁、秋风、衰荷、黄芦、梧桐、菊桂为物候底色，情感几乎被 “思乡怀人” 占满。“露从今夜白，月是故乡明” 把露的洁白与月的明亮一并归给故乡，“戍鼓断人行，边秋一雁声”“有弟皆分散，无家问死生”“寄书长不达”，乱世离散使这一节气的凉意直接成了人的凉意；“有兄在淮楚，有弟在蜀道，万里何时来”，是同一主题的另一种写法。客居者的感受更细：“客意惊秋半，炎凉信转蓬”“寓园秋，故园秋”“孤舟待明月”，节候推移被当作身世漂流的刻度。第二重是物我同衰的悲感，“惨澹老容颜，冷落秋怀抱”“不堪翠减红销际，更在江清月冷中”“盛衰老眼依然在”，残荷与老眼互为镜象，“痛哭空怀古，狂歌拟送穷” 更把秋写成穷愁的时节。不过白露诗里也有难得的暖色与清欢，“是时禾黍登，充积遍都鄙”“人言田家乐”“七月已全收”，丰收被写成太平之象；“河汉云消溢素光，重开樽酒据绳床”“白露收残月，清风散晓霞”“时闻兰杜香”，又见秋夜的清朗。离思、衰感与丰年之喜、清夜之赏并置，构成白露独有的复杂情感。", "culture": "白露处在仲秋之初，白露、鸿雁、秋风、衰荷、梧桐、菊桂是标志性物候，三候为鸿雁来、玄鸟归、群鸟养羞，“边秋一雁声”“早雁声中露欲霜” 正应 “鸿雁来”，候鸟成为节气最可靠的信号。节气之名取自秋金之色，“白露为霜” 直承《诗经・蒹葭》的露霜意象，“载授我衣” 则接《豳风・七月》的授衣传统，白露因此兼有物候与衣候的双重身份。秋收在此已成实事，“是时禾黍登，充积遍都鄙”“黍稷如岵”“七月已全收”，但诗里也写出收成背后的计较，“租赋以输官，所馀足储峙。不然风雪至，冻馁及妻子”，田家之乐与赋税之忧并置，“太平元有象，治世乃如此”“丰年伊何，维民之德” 则把丰年升格为治世的凭证，四言颂体直承《诗经》的礼乐传统。到了士人一端，则见 “今朝学圃农”“痛哭空怀古，狂歌拟送穷” 的退居与自嘲，以及 “月是故乡明” 所确立的思乡范式。露之白、雁之来与人之离相融，使白露成为连通自然凝露、秋收赋役与思乡怀人传统的特殊节气。"}, {"name": "秋分", "season": "秋", "poems": [{"dyn": "唐", "poet": "杜甫", "title": "晚晴", "text": "返照斜初彻，浮云薄未归。\n江虹明远饮，峡雨落余飞。\n凫雁终高去，熊罴觉自肥。\n秋分客尚在，竹露夕微微。", "img": "浮云 雨 凫雁 竹 夕阳"}, {"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·秋分八月中", "text": "琴弹南吕调，风色已高清。\n云散飘飖影，雷收振怒声。\n乾坤能静肃，寒暑喜均平。\n忽见新来雁，人心敢不惊。", "img": "雷 雁"}, {"dyn": "宋", "poet": "陆游", "title": "秋分后顿凄冷有感", "text": "今年秋气早，木落不待黄。\n蟋蟀当在宇，遽已近我床。\n况我老当逝，且复小彷徉。\n岂无一樽酒，亦有书在傍。\n饮酒读古书，慨然想黄唐。\n耄矣狂未除，谁能药膏肓。", "img": "蟋蟀"}, {"dyn": "宋", "poet": "谢逸", "title": "点绛唇·金气秋分", "text": "金气秋分，风清露冷秋期半。\n凉蟾光满，桂子飘香远。\n素练宽衣，仙仗明飞观。\n霓裳乱，银桥人散，\n吹彻昭华管。", "img": "风 露 凉蟾(满月) 桂子"}, {"dyn": "元", "poet": "杨公远", "title": "三用韵（其三）", "text": "屋头明月上，此夕又秋分。\n千里人俱共，三杯酒自醺。\n河清疑有水，夜永喜无云。\n桂树婆娑影，天香满世闻。", "img": "明月 桂树"}, {"dyn": "明", "poet": "孙作", "title": "客中秋夜", "text": "故园应露白，凉夜又秋分。\n月皎空山静，天清一雁闻。\n感时愁独在，排闷酒初醺。\n豆子南山熟，何年得自耘。", "img": "露 月 雁"}, {"dyn": "明", "poet": "钱月龄", "title": "秋分日同友人山行", "text": "羁愁暂摆作山行，秋日平分气转清。\n溪影照人风已息，稻香沾袖雨初晴。\n古今在眼青山色，岁序惊心白雁声。\n更喜同游俱物表，搴芝坐石看云生。", "img": "溪 稻 白雁"}, {"dyn": "清", "poet": "柴静仪", "title": "秋分日忆用济", "text": "遇节思吾子，吟诗对夕曛。\n燕将明日去，秋向此时分。\n逆旅空弹铗，生涯只卖文。\n归帆宜早挂，莫待雪纷纷。", "img": "燕"}, {"dyn": "清", "poet": "黄景仁", "title": "道中秋分", "text": "万态深秋去不穷，客程常背伯劳东。\n残星水冷鱼龙夜，独雁天高阊阖风。\n瘦马羸童行得得，高原古木听空空。\n欲知道路看人意，五度清霜压断蓬。", "img": "雁 清霜"}, {"dyn": "清", "poet": "顾太清", "title": "金风玉露相逢曲·丙寅中秋，是日秋分", "text": "天光如水，月光如镜，\n一片清辉皎洁。吹来何处桂花香，\n恰今日、平分秋色。芭蕉叶老，\n梧桐叶落，老健春寒秋热。\n须知光景不多时，能几见、团圆佳节。", "img": "桂花 芭蕉叶 梧桐叶"}, {"dyn": "清", "poet": "全祖望", "title": "访秋分得玉溪诗中吹字韵", "text": "吾意正萧瑟，况逢秋半时。\n谁家临水处，定有拒霜枝。\n日落烟光淡，风凉衣带吹。\n东城多野色，病叟亦忘疲。", "img": "霜枝 落日 凉风"}], "stats": [], "emotion": "秋分诗词以浮云、峡雨、竹露、凉蟾、桂子、雁、稻香为物候底色，情感的第一层是 “均” 与 “清”。“乾坤能静肃，寒暑喜均平”“秋日平分气转清”“恰今日、平分秋色”，暑寒各半、昼夜相均，天地一时安静下来，人也随之清朗，“搴芝坐石看云生”“稻香沾袖雨初晴” 便是这种清冷里的舒展。但 “秋半” 同时是全组中最锋利的时刻，“风清露冷秋期半”“岁序惊心白雁声”“忽见新来雁，人心敢不惊”，过半即意味着衰之始，“须知光景不多时，能几见、团圆佳节”，团圆之乐里已含着紧迫。于是有第二层情感：客居与归思。“秋分客尚在”“故园应露白”“逆旅空弹铗，生涯只卖文”“归帆宜早挂，莫待雪纷纷”，秋分像一个催归的节气，雁尚南来而人犹未返；行旅者则 “客程常背伯劳东”“五度清霜压断蓬”，写尽飘零。第三层是赏月团圆的暖意，“千里人俱共，三杯酒自醺”“桂树婆娑影，天香满世闻”“凉蟾光满”，与老病之叹（“耄矣狂未除”“病叟亦忘疲”）并置，冷暖相衬，构成秋分独有的复杂情感。", "culture": "秋分处在仲秋之中，昼夜均而寒暑平，浮云、竹露、凉蟾、桂子、雁、稻香是标志性物候，三候为雷始收声、蛰虫坯户、候鸟来，“雷收振怒声”“蟋蟀当在宇，遽已近我床” 正是候应的直写，天地由喧动转为静肃。“琴弹南吕调” 以南吕之律标八月，“寒暑喜均平”“平分秋色” 则把节气最核心的天文含义写成诗意，昼夜与阴阳在此各得其半，秋分之名由此而立。它与中秋月事几乎重合，“凉蟾光满，桂子飘香远”“银桥人散，吹彻昭华管”“桂树婆娑影，天香满世闻”，月宫的传说与团圆的家常一并进入这一节气，赏月、桂香、团圆成为它的节俗底色。农事上 “稻香沾袖”“豆子南山熟”，收成已近尾声；“归帆宜早挂，莫待雪纷纷” 则见秋分作为行旅期限的意义，过了此时便要备寒。士人一端，“逆旅空弹铗，生涯只卖文”“饮酒读古书，慨然想黄唐” 写尽羁旅与抱负，而 “谁家临水处，定有拒霜枝” 又以木芙蓉的晚秀留一点秋色。均平之理、月桂之俗与羁旅之思相融，使秋分成为连通阴阳平衡、团圆节俗与士人出处之叹的特殊节气。"}, {"name": "寒露", "season": "秋", "poems": [{"dyn": "唐", "poet": "戴察", "title": "月夜梧桐叶上见寒露", "text": "萧疏桐叶上，月白露初团。\n滴沥清光满，荧煌素彩寒。\n风摇愁玉坠，枝动惜珠干。\n气冷疑秋晚，声微觉夜阑。\n凝空流欲遍，润物净宜看。\n莫厌窥临倦，将晞聚更难。", "img": "桐叶 月 风 露"}, {"dyn": "唐", "poet": "白居易", "title": "池上", "text": "袅袅凉风动，凄凄寒露零。\n兰衰花始白，荷破叶犹青。\n独立栖沙鹤，双飞照水萤。\n若为寥落境，仍值酒初醒。", "img": "凉风 兰 荷 沙鹤"}, {"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·寒露九月节", "text": "寒露惊秋晚，朝看菊渐黄。\n千家风扫叶，万里雁随阳。\n化蛤悲群鸟，收田畏早霜。\n因知松柏志，冬夏色苍苍。", "img": "菊 雁 群鸟 松柏 早霜"}, {"dyn": "唐", "poet": "王昌龄", "title": "斋心", "text": "女萝覆石壁，溪水幽朦胧。\n紫葛蔓黄花，娟娟寒露中。\n朝饮花上露，夜卧松下风。\n云英化为水，光采与我同。\n日月荡精魄，寥寥天宇空。", "img": "黄花 溪水 露 风"}, {"dyn": "唐", "poet": "刘沧", "title": "秋日望西阳", "text": "古木苍苔坠几层，行人一望旅情增。\n太行山下黄河水，铜雀台西武帝陵。\n风入蒹葭秋色动，雨余杨柳暮烟凝。\n野花似泣红妆泪，寒露满枝枝不胜。", "img": "古木 蒹葭 暮烟 野花 杨柳"}, {"dyn": "唐", "poet": "韩愈", "title": "木芙蓉", "text": "新开寒露丛，远比水间红。\n艳色宁相妒，嘉名偶自同。\n采江官渡晚，搴木古祠空。\n愿得勤来看，无令便逐风。", "img": "风 水间红(芙蓉花) 露"}, {"dyn": "宋", "poet": "王安石", "title": "八月十九日试院梦冲卿", "text": "空庭得秋长漫漫，寒露入暮愁衣单。\n喧喧人语已成市，白日未到扶桑间。\n永怀所好却成梦，玉色仿佛开心颜。\n逆知后应不复隔，谈笑明月相与闲。", "img": "扶桑  明月"}, {"dyn": "宋", "poet": "柳永", "title": "玉蝴蝶·望处雨收云断", "text": "望处雨收云断，凭阑悄悄，目送秋光。晚景萧疏，堪动宋玉悲凉。水风轻、蘋花渐老，月露冷、梧叶飘黄。遣情伤，故人何在，烟水茫茫。\n\n难忘，文期酒会，几孤风月，屡变星霜。海阔山遥，未知何处是潇湘。念双燕、难凭远信，指暮天、空识归航。黯相望，断鸿声里，立尽斜阳。", "img": "风 月 梧叶 烟水 双燕 暮天 断鸿 斜阳 蘋花 露"}, {"dyn": "宋", "poet": "郭印", "title": "秋日即事", "text": "篱边准拟嗅清香，菊蕊真同佛斋妆。\n屈指重阳能几许，夜来寒露已为霜。", "img": "菊蕊 霜 寒露"}, {"dyn": "宋", "poet": "邵雍", "title": "秋怀三十六首（选一）", "text": "寒露缀衰草，凄风摇晚林。\n鸟声上复下，天气晴还阴。\n节改一时事，人怀千古心。\n谁云子期死，举世无知音。", "img": "寒露 衰草 凄风 晚林 鸟声"}, {"dyn": "明", "poet": "唐寅", "title": "败荷鹡鸰图", "text": "飞唤行摇类急难，野田寒露欲成团。\n莫言四海皆兄长，骨肉而今冷眼看。", "img": "野田 寒露"}, {"dyn": "明", "poet": "邱云霄", "title": "寒露同李洗松宿方塘书舍", "text": "露重怜今夕，秋深试薄寒。\n溪声乱篱落，月色动柴关。\n菊密欲藏径，花娇故傍栏。\n相看疑梦寐，秉烛问更阑。", "img": "露 月色 菊"}], "stats": [], "emotion": "这组寒露诗词以桐叶、秋露、寒菊、归雁、凉风等暮秋物候意象为载体，情感层次丰富。露凝将霜、菊黄雁归、草木凋残的寒露景象，常唤起诗人对美好秋景短暂易逝的怜惜，是对时序向晚、秋气肃杀的沉静体察；当同样的寒露风物落入羁旅、失意者眼中，便生出反差，诗人借残荷衰草、孤鸿冷月抒发漂泊怀人、知音难遇的落寞，还有篇目由野田寒露起兴，感慨人情凉薄。也有诗人面对秋山溪露心境冲淡安然，于松风黄花间安顿自我，寄托坚贞自持的志向与隐逸之思，不同的人生境遇，让同一组寒露物候承载了迥然相异的情绪。", "culture": "这组诗作紧扣寒露节气独有的物候气象，捕捉秋深气冷、露结欲霜、鸿雁南迁、兰衰桐落、菊蕊渐黄的暮秋节律，记录风、月、暮烟、秋雨等秋日天象，是古人依靠自然变化辨识节令的体现。作品承继古典悲秋文学传统，菊、松柏、断鸿、蒹葭等意象各有文化寄托，同时留存秋收畏早霜的农事经验，融入怀古、天人合一的隐逸理念，寒露风物成为媒介，承载着古人对时节流转、君子操守、人世聚散的理解。"}, {"name": "霜降", "season": "秋", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·霜降九月中", "text": "风卷清云尽，空天万里霜。\n野豺先祭月，仙菊遇重阳。\n秋色悲疏木，鸿鸣忆故乡。\n谁知一樽酒，能使百秋亡。", "img": "风 云 霜 野豺 月 仙菊 疏木 鸿鸣"}, {"dyn": "唐", "poet": "元稹", "title": "赋得九月尽（秋字）", "text": "霜降三旬后，蓂馀一叶秋。\n玄阴迎落日，凉魄尽残钩。\n半夜灰移琯，明朝帝御裘。\n潘安过今夕，休咏赋中愁。", "img": "霜 叶 落日"}, {"dyn": "唐", "poet": "张九龄", "title": "秋晚登楼望南江入始兴郡路", "text": "潦收沙衍出，霜降天宇晶。\n伏槛一长眺，津途多远情。\n思来江山外，望尽烟云生。\n滔滔不自辨，役役且何成。\n我来飒衰鬓，孰云飘华缨。\n枥马苦踡跼，笼禽念遐征。\n岁阴向晼晚，日夕空屏营。\n物生贵得性，身累由近名。\n内顾觉今是，追叹何时平。", "img": "烟云 霜  天宇"}, {"dyn": "唐", "poet": "白居易", "title": "岁晚", "text": "霜降水返壑，风落木归山。\n冉冉岁将宴，物皆复本源。\n何此南迁客，五年独未还。\n命屯分已定，日久心弥安。\n亦尝心与口，静念私自言。\n去国固非乐，归乡未必欢。\n何须自生苦，舍易求其难。", "img": "风 木 霜"}, {"dyn": "唐", "poet": "李商隐", "title": "霜月", "text": "初闻征雁已无蝉，百尺楼高水接天。\n青女素娥俱耐冷，月中霜里斗婵娟。", "img": "雁 蝉 月 霜"}, {"dyn": "唐", "poet": "张继", "title": "枫桥夜泊", "text": "月落乌啼霜满天，江枫渔火对愁眠。\n姑苏城外寒山寺，夜半钟声到客船。", "img": "月 乌 霜"}, {"dyn": "唐", "poet": "杜牧", "title": "山行", "text": "远上寒山石径斜，白云生处有人家。\n停车坐爱枫林晚，霜叶红于二月花。", "img": "白云 枫林 霜叶"}, {"dyn": "唐", "poet": "刘长卿", "title": "九日登李明府北楼", "text": "九日登高望，苍苍远树低。\n人烟湖草里，山翠县楼西。\n霜降鸿声切，秋深客思迷。\n无劳白衣酒，陶令自相携。", "img": "树 草 霜 鸿声"}, {"dyn": "宋", "poet": "苏轼", "title": "南乡子·重九涵辉楼呈徐君猷", "text": "霜降水痕收，浅碧鳞鳞露远洲。酒力渐消风力软，飕飕，破帽多情却恋头。\n\n佳节若为酬，但把清尊断送秋。万事到头都是梦，休休，明日黄花蝶也愁。", "img": "霜 风 黄花"}, {"dyn": "宋", "poet": "苏轼", "title": "赠刘景文", "text": "荷尽已无擎雨盖，菊残犹有傲霜枝。\n一年好景君须记，最是橙黄橘绿时。", "img": "荷 菊"}, {"dyn": "元", "poet": "王冕", "title": "舟中杂纪·其十", "text": "老树转斜晖，人家水竹围。\n露深花气冷，霜降蟹膏肥。\n沽酒心何壮，看山思欲飞。\n操舟有吴女，双桨唱新归。", "img": "老树 竹 露 霜"}, {"dyn": "明", "poet": "王夫之", "title": "南中霜降", "text": "北候怀青女，南飙拂白蘋。\n墟烟深漠漠，江草故鳞鳞。\n翠袖寒犹薄，黄华泪已新。\n炎洲无限橘，谁与寄湘津。", "img": "白蘋 江草 黄华(菊）"}, {"dyn": "明", "poet": "郑茂", "title": "都门霜降日作", "text": "风雨连朝动客愁，笳声呜咽满边楼。\n卷帘何事看新月，一夜霜寒木叶秋。", "img": "月 霜 寒木 叶"}], "stats": [], "emotion": "这组霜降诗词以霜、鸿雁、枫林、残菊、疏木等暮秋物候意象为载体，情感层次丰富。寒霜初降、雁向南飞、木叶凋零的霜降景象，常唤起诗人岁暮将近的时序之感，既有霜叶明艳、菊枝傲寒带来的赏秋欣喜，也有登高望远、孤舟夜泊生发的羁旅乡愁；部分诗人面对万物归根的秋景，生出对功名束缚的反思与随遇而安的通透，也有借秋菊、橙橘抒写不屈风骨的寄托。不同的人生境遇，让同一组霜降物候承载了迥然相异的情绪。", "culture": "这组诗作紧扣霜降节气的物候气象，捕捉气凝为霜、鸿雁南迁、草木摇落、菊盛枫红的暮秋节律，记录长风、冷月、烟云、秋雨等秋日天象，是古人依托自然征象感知节令流转的体现。作品延续悲秋传统，霜、鸿雁、枫林、黄菊都是经典秋意符号，融入重阳登高、豺祭这类节令习俗，也暗含岁晚归根的生命观念，霜降风物成为载体，承载着古人对时序变化、品格坚守、人世聚散的理解。"}, {"name": "立冬", "season": "冬", "poems": [{"dyn": "唐", "poet": "李白", "title": "立冬", "text": "冻笔新诗懒写，寒炉美酒时温。\n醉看墨花月白，恍疑雪满前村。", "img": "花 月 雪"}, {"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·立冬十月节", "text": "霜降向人寒，轻冰渌水漫。\n蟾将纤影出，雁带几行残。\n田种收藏了，衣裘制造看。\n野鸡投水日，化蜃不将难。", "img": "霜 蟾 雁 野鸡"}, {"dyn": "唐", "poet": "王维", "title": "山中", "text": "荆溪白石出，天寒红叶稀。\n山路元无雨，空翠湿人衣。", "img": "红叶 雨"}, {"dyn": "唐", "poet": "白居易", "title": "早冬", "text": "十月江南天气好，可怜冬景似春华。\n霜轻未杀萋萋草，日暖初干漠漠沙。\n老柘叶黄如嫩树，寒樱枝白是狂花。\n此时却羡闲人醉，五马无由入酒家。", "img": "霜 草 叶 花 日"}, {"dyn": "宋", "poet": "陆游", "title": "初冬（其一）", "text": "平生诗句领流光，绝爱初冬万瓦霜。\n枫叶欲残看愈好，梅花未动意先香。\n暮年自适何妨退，短景无营亦自长。\n况有小儿同此趣，一窗相对弄朱黄。", "img": "霜 枫叶 梅"}, {"dyn": "宋", "poet": "钱时", "title": "立冬前一日霜对菊有感", "text": "昨夜清霜冷絮裯，纷纷红叶满阶头。\n园林尽扫西风去，惟有黄花不负秋。", "img": "霜 红叶 西风 黄花"}, {"dyn": "宋", "poet": "释文珦", "title": "立冬日野外行吟", "text": "吟行不惮遥，风景尽堪抄。\n天水清相入，秋冬气始交。\n饮虹消海曲，宿雁下塘坳。\n归去须乘月，松门许夜敲。", "img": "雁 月 天 水"}, {"dyn": "宋", "poet": "范成大", "title": "立冬夜舟中作", "text": "人逐年华老，寒随雨意增。\n山头望樵火，水底见渔灯。\n浪影生千叠，沙痕没几棱。\n峨眉欲还观，须待到晨兴。", "img": "雨  沙"}, {"dyn": "元", "poet": "仇远", "title": "立冬即事二首·其一", "text": "细雨生寒未有霜，庭前木叶半青黄。\n小春此去无多日，何处梅花一绽香。", "img": "雨 霜 木叶 梅花"}, {"dyn": "元", "poet": "陆文圭", "title": "立冬", "text": "旱久何当雨，秋深渐入冬。\n黄花犹带露，红叶已随风。\n边思吹寒角，村歌相晚舂。\n篱门日高卧，衰懒愧无功。", "img": "雨 黄花 露 红叶 风"}, {"dyn": "明", "poet": "王稚登", "title": "立冬", "text": "秋风吹尽旧庭柯，黄叶丹枫客里过。\n一点禅灯半轮月，今宵寒较昨宵多。", "img": "秋风 黄叶 月"}, {"dyn": "清", "poet": "陈维崧", "title": "喜迁莺·立冬", "text": "西风忒峭。把似锦浓秋，霎时都扫。林影添黄，潭痕减翠，易损他乡怀抱。瓮头索郎未熟，坌口猎徒还少。燕市畔，渐消寒九九，排当画稿。\n\n那晓。人世事，月令岁华，惯是田家好。摘菜淹菹，燃糠煨芋，夜火村村打稻。惆怅年来残夜，催著朝衫偏早。凭谁说，向茅檐曝背，溪南诗老。", "img": "西风 林"}], "stats": [], "emotion": "这组立冬前后诗词以霜、红叶、寒月、初梅、归雁等秋冬之交的物候意象为载体，情感层次丰富。秋冬交替、寒气渐生、草木换色的景象，常唤起诗人对时序推移、岁华向晚的体察；江南冬景温润如春，又能生出欣赏清和景致的欣喜，也有面对残枫黄花、冷月寒雨时，羁旅之人涌起的客愁。不少诗人借初冬清景安放身心，流露归闲自适、淡然忘机的心境，不同的人生境遇，让这一组秋冬物候承载了各不相同的情绪。", "culture": "这组诗作紧扣立冬时节秋冬气交的特点，捕捉初霜、寒雨、雁归、红叶零落、梅孕暗香的物候变化，记录冷月、西风、晴日等天象，是古人凭自然景象分辨节令的体现。诗作延续秋暮入冬的时序书写传统，枫叶、黄菊、寒梅都是富有寓意的经典意象，还写到秋收完毕、腌制菜蔬、煨芋打稻等乡土农事，将节令风物、田园生活与文人的隐逸情怀相融，承载着古人对时节流转与生活本真的理解。"}, {"name": "小雪", "season": "冬", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·小雪十月中", "text": "莫怪虹无影，如今小雪时。\n阴阳依上下，寒暑喜分离。\n满月光天汉，长风响树枝。\n横琴对渌醑，犹自敛愁眉。", "img": "小雪 月 风 树枝"}, {"dyn": "唐", "poet": "白居易", "title": "问刘十九", "text": "绿蚁新醅酒，红泥小火炉。\n晚来天欲雪，能饮一杯无。", "img": "雪 蚁"}, {"dyn": "唐", "poet": "戴叔伦", "title": "小雪", "text": "花雪随风不厌看，更多还肯失林峦。\n愁人正在书窗下，一片飞来一片寒。", "img": "雪 林峦"}, {"dyn": "唐", "poet": "徐铉", "title": "和萧郎中小雪日作", "text": "征西府里日西斜，独试新炉自煮茶。\n篱菊尽来低覆水，塞鸿飞去远连霞。\n寂寥小雪闲中过，斑驳轻霜鬓上加。\n算得流年无奈处，莫将诗句祝苍华。", "img": "菊 鸿 小雪 霜"}, {"dyn": "唐", "poet": "李咸用", "title": "小雪", "text": "散漫阴风里，天涯不可收。\n压松犹未得，扑石暂能留。\n阁静萦吟思，途长拂旅愁。\n崆峒山北面，早想玉成丘。", "img": "阴风 松 山"}, {"dyn": "唐", "poet": "张登", "title": "小雪日戏题绝句", "text": "甲子徒推小雪天，刺梧犹绿槿花然。\n融和长养无时歇，却是炎洲雨露偏。", "img": "小雪 梧 槿花 雨露"}, {"dyn": "唐", "poet": "陈羽", "title": "夜泊荆溪", "text": "小雪已晴芦叶暗，长波乍急鹤声嘶。\n孤舟一夜宿流水，眼看山头月落溪。", "img": "小雪 芦叶 鹤 山 月 溪"}, {"dyn": "宋", "poet": "陆游", "title": "初寒", "text": "久雨重阳后，清寒小雪前。\n拾薪椎髻仆，卖菜掘头船。\n薄米全家粥，空床故物毡。\n身犹付一歃，名字更须传。", "img": "雨 小雪"}, {"dyn": "宋", "poet": "黄庭坚", "title": "春近四绝句（其一）", "text": "小雪晴沙不作泥，疏帘红日弄朝晖。\n年华已伴梅梢晚，春色先从草际归。", "img": "小雪 红日 梅 草"}, {"dyn": "宋", "poet": "释善珍", "title": "小雪", "text": "云暗初成霰点微，旋闻蔌蔌洒窗扉。\n最愁南北犬惊吠，兼恐北风鸿退飞。\n梦锦尚堪裁好句，鬓丝那可织寒衣。\n拥炉睡思难撑拄，起唤梅花为解围。", "img": "云 风 鸿 梅花"}, {"dyn": "清", "poet": "曹雪芹", "title": "残菊", "text": "露凝霜重渐倾欹，宴赏才过小雪时。\n蒂有余香金淡泊，枝无全叶翠离披。\n半床落月蛩声病，万里寒云雁阵迟。\n明岁秋风知再会，暂时分手莫相思。", "img": "露 霜 小雪 叶 月 寒云 雁 风"}], "stats": [], "emotion": "这组小雪诗词以微雪、朔风、寒月、残菊、征鸿、早梅等物候意象为载体，情感层次丰富。小雪初临、虹藏不见、寒气蔓延的景象，常唤起诗人对阴阳交替、时序入冬的沉静体察；细雪飘飞、炉火温酒的清寒之景，可以生出邀约同饮的温情，而飞雪入窗、孤舟夜宿的画面，又容易勾起羁旅漂泊、流年暗逝的愁绪。也有诗人于晴日小雪里看见梅梢草色，感知潜藏的春意，心怀期许，不同的人生境遇，让同一组小雪物候承载了迥然相异的情绪。", "culture": "这组诗作紧扣小雪节气的物候气象，捕捉虹藏、微霰初落、霜寒加重、鸿雁南飞、草木凋残的入冬节律，记录长风、寒云、晴日、夜雨等天象，是古人依靠自然征象辨识节令流转的体现。作品延续冬日时序书写传统，雪、寒梅、归雁、残菊都是经典意象，兼顾山野行旅、村居生计与围炉闲居的日常，小雪风物成为媒介，承载着古人对阴阳消长、岁月变迁与人间冷暖的理解。"}, {"name": "大雪", "season": "冬", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·大雪十一月节", "text": "积阴成大雪，看处乱霏霏。\n玉管鸣寒夜，披书晓绛帷。\n黄钟随气改，鴳鸟不鸣时。\n何限苍生类，依依惜暮晖。", "img": "大雪 鸟"}, {"dyn": "唐", "poet": "柳宗元", "title": "江雪", "text": "千山鸟飞绝，万径人踪灭。\n孤舟蓑笠翁，独钓寒江雪。", "img": "鸟 江雪"}, {"dyn": "唐", "poet": "岑参", "title": "白雪歌送武判官归京", "text": "北风卷地白草折，胡天八月即飞雪。\n忽如一夜春风来，千树万树梨花开。\n散入珠帘湿罗幕，狐裘不暖锦衾薄。\n将军角弓不得控，都护铁衣冷难着。\n瀚海阑干百丈冰，愁云惨淡万里凝。\n中军置酒饮归客，胡琴琵琶与羌笛。\n纷纷暮雪下辕门，风掣红旗冻不翻。\n轮台东门送君去，去时雪满天山路。\n山回路转不见君，雪上空留马行处。", "img": "风 草 飞雪（梨花）海 冰 云"}, {"dyn": "唐", "poet": "白居易", "title": "夜雪", "text": "已讶衾枕冷，复见窗户明。\n夜深知雪重，时闻折竹声。", "img": "雪 竹"}, {"dyn": "唐", "poet": "高骈", "title": "对雪", "text": "六出飞花入户时，坐看青竹变琼枝。\n如今好上高楼望，盖尽人间恶路岐。", "img": "竹 飞花（雪)"}, {"dyn": "唐", "poet": "卢纶", "title": "和张仆射塞下曲·其三", "text": "月黑雁飞高，单于夜遁逃。\n欲将轻骑逐，大雪满弓刀。", "img": "月 雁 大雪"}, {"dyn": "唐", "poet": "刘长卿", "title": "逢雪宿芙蓉山主人", "text": "日暮苍山远，天寒白屋贫。\n柴门闻犬吠，风雪夜归人。", "img": "犬 风雪"}, {"dyn": "唐", "poet": "高适", "title": "别董大", "text": "千里黄云白日曛，北风吹雁雪纷纷。\n莫愁前路无知己，天下谁人不识君。", "img": "黄云 风 雁 雪"}, {"dyn": "宋", "poet": "陆游", "title": "大雪", "text": "大雪江南见未曾，今年方始是严凝。\n巧穿帘罅如相觅，重压林梢欲不胜。\n毡幄掷卢忘夜睡，金羁立马怯晨兴。\n此生自笑功名晚，空想黄河彻底冰。", "img": "大雪 林梢 黄河"}, {"dyn": "宋", "poet": "杨万里", "title": "观雪", "text": "坐看深来尺许强，偏于薄暮发寒光。\n半空舞倦居然懒，一点风来特地忙。\n落尽琼花天不惜，封它梅蕊玉无香。\n倩谁细橪成汤饼，换却人间烟火肠。", "img": "梅蕊 风 琼花（雪）"}, {"dyn": "宋", "poet": "卢梅坡", "title": "雪梅·其一", "text": "梅雪争春未肯降，骚人阁笔费评章。\n梅须逊雪三分白，雪却输梅一段香。", "img": "梅 雪"}, {"dyn": "元", "poet": "黄庚", "title": "雪", "text": "片片随风整复斜，飘来老鬓觉添华。\n江山不夜月千里，天地无私玉万家。\n远岸未春飞柳絮，前村破晓压梅花。\n羔羊金帐应粗俗，自掬冰泉煮石茶。", "img": "风 月 梅花 柳絮（雪）"}, {"dyn": "明", "poet": "陶宗仪", "title": "十一月朔大雪节早见雪", "text": "狂风昨夜吼棱棱，寒压重衾若覆冰。\n节气今朝逢大雪，清晨瓦上雪微凝。", "img": "狂风 雪"}], "stats": [], "emotion": "这组大雪诗词以飞雪、北风、寒竹、归雁、寒梅等隆冬物候意象为载体，情感层次丰富。大雪纷飞、天地凝寒、飞鸟匿迹的景象，常唤起诗人对阴气盛极、深冬来临的沉静体察；漫天白雪既可生出赏雪抒怀、托雪寄愿的旷达，边塞风雪里又交织送别友人的不舍与征战的豪壮，孤舟寒江、风雪柴门的画面，也藏着孤寂清峭或是盼人归来的温情。还有诗人观梅雪相争，生出品鉴风物的雅趣，不同的人生境遇，让同一组大雪物候承载了迥然相异的情绪。", "culture": "这组诗作紧扣大雪节气的物候气象，捕捉阴气积聚、大雪纷飞、鸟兽蛰伏、江河冰封的深冬节律，记录朔风、寒云、冷月等天象，是古人依托自然征象感知节令流转的体现。作品延续冬日咏雪的文学传统，飞雪、寒梅、孤雁都是经典意象，融入边塞、村居、书斋等不同场景，大雪风物成为媒介，承载着古人对阴阳消长、天地清肃、人世悲欢与风骨志趣的理解。"}, {"name": "冬至", "season": "冬", "poems": [{"dyn": "唐", "poet": "杜甫", "title": "小至", "text": "天时人事日相催，冬至阳生春又来。\n刺绣五纹添弱线，吹葭六琯动浮灰。\n岸容待腊将舒柳，山意冲寒欲放梅。\n云物不殊乡国异，教儿且覆掌中杯。", "img": "柳 梅"}, {"dyn": "唐", "poet": "杜甫", "title": "冬至", "text": "年年至日长为客，忽忽穷愁泥杀人。\n江上形容吾独老，天边风俗自相亲。\n杖藜雪后临丹壑，鸣玉朝来散紫宸。\n心折此时无一寸，路迷何处见三秦。", "img": "雪"}, {"dyn": "宋", "poet": "苏辙", "title": "冬至雪", "text": "一气潜萌九地中，雪花微落四无风。\n初阳便有回天力，宿瘴徐看卷地空。\n家酿再投犹恨薄，官酤多取定无功。\n时人浅陋终无益，径就天公借一丰。", "img": "雪 风 阳"}, {"dyn": "唐", "poet": "白居易", "title": "冬至夜", "text": "老去襟怀常濩落，病来须鬓转苍浪。\n心灰不及炉中火，鬓雪多于砌下霜。\n三峡南宾城最远，一年冬至夜偏长。\n今宵始觉房栊冷，坐索寒衣托孟光。", "img": "雪 霜"}, {"dyn": "唐", "poet": "杜牧", "title": "冬至日遇京使发寄舍弟", "text": "远信初凭双鲤去，他乡正遇一阳生。\n尊前岂解愁家国，辇下唯能忆弟兄。\n旅馆夜忧姜被冷，暮江寒觉晏裘轻。\n竹门风过还惆怅，疑是松窗雪打声。", "img": "风 雪 江"}, {"dyn": "唐", "poet": "韩偓", "title": "冬至夜作", "text": "中宵忽见动葭灰，料得南枝有早梅。\n四野便应枯草绿，九重先觉冻云开。\n阴冰莫向河源塞，阳气今从地底回。\n不道惨舒无定分，却忧蚊响又成雷。", "img": "早梅 枯草 冻云  雷"}, {"dyn": "宋", "poet": "陆游", "title": "辛酉冬至", "text": "今日日南至，吾门方寂然。\n家贫轻过节，身老怯增年。\n毕祭皆扶拜，分盘独早眠。\n惟应探春梦，已绕镜湖边。", "img": "镜湖"}, {"dyn": "宋", "poet": "苏轼", "title": "冬至日独游吉祥寺", "text": "井底微阳回未回，萧萧寒雨湿枯荄。\n何人更似苏夫子，不是花时肯独来。", "img": "寒雨"}, {"dyn": "宋", "poet": "朱淑真", "title": "冬至", "text": "黄钟应律好风催，阴伏阳升淑气回。\n葵影便移长至日，梅花先趁小寒开。\n八神表日占和岁，六管飞葭动细灰。\n已有岸旁迎腊柳，参差又欲领春来。", "img": "梅 柳"}, {"dyn": "宋", "poet": "方岳", "title": "冬至", "text": "至日观书不几行，梅梢横月欲昏黄。\n汉宫红影无人见，未必能添一线长。", "img": "梅 月"}, {"dyn": "元", "poet": "马臻", "title": "至节即事·其一", "text": "天街晓色瑞烟浓，名纸相传尽贺冬。\n绣幕家家浑不卷，呼卢笑语自从容。", "img": "瑞烟"}, {"dyn": "明", "poet": "董其昌", "title": "长安冬至", "text": "子月风光雪后看，新阳一缕动长安。\n禁钟乍应云门面，宝树先驱黍谷寒。", "img": "雪 阳 树"}], "stats": [], "emotion": "这组冬至诗词以早梅、待舒杨柳、寒雪、冻云、葭灰等物候意象为载体，情感层次丰富。冬至阴极阳生、昼渐回升的节候特点，常唤起诗人对阳气潜萌、春机暗蓄的体察，生出期盼回暖的欣喜；同样的物候落在羁旅游子、贫病老者眼中，便化作客居漂泊、年华老去的愁闷与思乡之痛。也有诗人于冬至守祭、观书闲居，或是随俗贺冬，保有平淡从容的心境，不同的人生境遇，让同一组冬至物候承载了迥然相异的情绪。", "culture": "这组诗作紧扣冬至 “一阳初生” 的节令特征，捕捉日影南至、葭灰飞动、梅蓄花苞、柳待回暖、寒雪犹存的物候变化，记录冻云、寒雨、晓烟等天象，是古人依靠自然节律与律管测候感知节气的体现。诗作延续冬至传统，包含添线、贺冬、家祭等节俗，借梅、柳象征新生生机，将阴阳消长的天道观念融入日常，冬至风物成为媒介，承载着古人对时序循环、家国乡情与生命起落的理解。"}, {"name": "小寒", "season": "冬", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·小寒十二月节", "text": "小寒连大吕，欢鹊垒新巢。\n拾食寻河曲，衔紫绕树梢。\n霜鹰近北首，雊雉隐丛茅。\n莫怪严凝切，春冬正月交。", "img": "鹊 霜鹰"}, {"dyn": "宋", "poet": "陆游", "title": "微雨", "text": "晡后气殊浊，黄昏月尚明。\n忽吹微雨过，便觉小寒生。\n树杪雀初定，草根虫已鸣。\n呼童取半臂，吾欲傍阶行。", "img": "月 微雨 雀 草 虫"}, {"dyn": "宋", "poet": "陆游", "title": "小园独酌", "text": "横林摇落微弄丹，深院萧条作小寒。\n秋气已高殊可喜，老怀多感自无欢。\n鹿初离母斑犹浅，橘乍经霜味尚酸。\n小酌一卮幽兴足，岂须落佩与颓冠。", "img": "林 鹿 菊 霜"}, {"dyn": "宋", "poet": "陆游", "title": "重九后风雨不止遂作小寒", "text": "菊枝欹倒不成丛，井上梧桐叶半空。\n射虎南山无复梦，雨蓑烟艇伴渔翁。", "img": "菊 梧桐叶"}, {"dyn": "宋", "poet": "范成大", "title": "早发竹下", "text": "结束晨妆破小寒，跨鞍聊得散疲顽。\n行冲薄薄轻轻雾，看放重重叠叠山。\n碧穗吹烟当树直，绿纹溪水趁桥湾。\n清禽百啭似迎客，正在有情无思间。", "img": "穗 溪水"}, {"dyn": "宋", "poet": "范成大", "title": "窗前木芙蓉", "text": "辛苦孤花破小寒，花心应似客心酸。\n更凭青女留连得，未作愁红怨绿看。", "img": "孤花"}, {"dyn": "宋", "poet": "黄庭坚", "title": "驻舆遣人寻访后山陈德方家", "text": "江雨蒙蒙作小寒，雪飘五老发毛斑。\n城中咫尺云横栈，独立前山望后山。", "img": "雨 雪 云"}, {"dyn": "宋", "poet": "陈与义", "title": "窦园醉中前后五绝句（其一）", "text": "东风吹雨小寒生，杨柳飞花乱晚晴。\n客子从今无可恨，窦家园里有莺声。", "img": "风 雨  杨柳 飞花（雪）"}, {"dyn": "宋", "poet": "郑刚中", "title": "送季平道中四绝（其一）", "text": "霜风落叶小寒天，去客依依马不鞭。\n我最平生苦离别，可能相送不凄然。", "img": "霜风 落叶"}, {"dyn": "元", "poet": "张昱", "title": "小寒", "text": "花外东风作小寒，轻红淡白满阑干。\n春光不与人怜惜，留得清明伴牡丹。", "img": "东风 花 牡丹"}, {"dyn": "元", "poet": "王寂", "title": "望月婆罗门·元夕", "text": "小寒料峭，一番春意换年芳。蛾儿雪柳风光。开尽星桥铁锁，平地泻银潢。记当时行乐，年少如狂，宦游异乡。\n\n对节物、只堪伤。冷落谯楼水淡月，燕寝余香。快呼伯雅，要洗我、穷愁九曲肠。休更问、勋业行藏。", "img": "雪 柳 月 燕"}, {"dyn": "明", "poet": "黄佐", "title": "小寒节有感", "text": "雨霁风恬始见花，野梅含笑正横斜。\n红芳此后周千里，绿树仍前荫万家。\n寒日自能明蔀障，轻雷应为蛰龙蛇。\n老来衰惫偏多感，时有新诗纪物华。", "img": "梅 树"}, {"dyn": "明", "poet": "祁顺", "title": "自褫亭冒雪至余吾", "text": "小寒今日初交节，同云一色浓阴结。\n谁剪银河不露痕，满天飞下琼瑶屑。", "img": "云 琼瑶（雪）"}], "stats": [], "emotion": "这组小寒诗词以喜鹊、霜鹰、寒梅、微雨、轻雪、疏林等物候意象为载体，情感层次丰富。小寒时节寒气犹重、冬春交替，鹊筑新巢、虫鸟微动、东风初至的景象，常唤起诗人对春意暗萌的体察；冷雨飘雪、花木萧条的景致，又容易勾起游子羁旅之苦、离别伤感与迟暮之叹。也有诗人趁寒出游、对花小酌，于清冷风物间寻得闲适自在，不同的人生境遇，让同一组小寒物候承载了迥然相异的情绪。", "culture": "这组诗作紧扣小寒冬春交接的节气特点，捕捉鹊始筑巢、雉鸟潜藏、霜雪犹存、东风微动、梅蕊初放的物候变化，记录微雨、浓云、冷月等天象，是古人借自然征象感知节令推移的体现。作品延续冬日咏物传统，鹊、梅、霜鹰都是富有寓意的经典意象，兼顾山野行游、送别、闲居等日常，小寒风物成为媒介，承载着古人对阴阳流转、岁时更替与悲欢际遇的理解。"}, {"name": "大寒", "season": "冬", "poems": [{"dyn": "唐", "poet": "元稹", "title": "咏廿四气诗·大寒十二月中", "text": "腊酒自盈樽，金炉兽炭温。\n大寒宜近火，无事莫开门。\n冬与春交替，星周月讵存。\n明朝换新律，梅柳待阳春。", "img": "梅 柳"}, {"dyn": "唐", "poet": "白居易", "title": "村居苦寒", "text": "八年十二月，五日雪纷纷。\n竹柏皆冻死，况彼无衣民。\n回观村闾间，十室八九贫。\n北风利如剑，布絮不蔽身。\n唯烧蒿棘火，愁坐夜待晨。\n乃知大寒岁，农者尤苦辛。\n顾我当此日，草堂深掩门。\n褐裘覆絁被，坐卧有余温。\n幸免饥冻苦，又无垄亩勤。\n念彼深可愧，自问是何人。", "img": "雪 竹 柏 风"}, {"dyn": "唐", "poet": "孟郊", "title": "苦寒吟", "text": "天寒色青苍，北风叫枯桑。\n厚冰无裂文，短日有冷光。\n敲石不得火，壮阴夺正阳。\n苦调竟何言，冻吟成此章。", "img": "风 冰"}, {"dyn": "宋", "poet": "邵雍", "title": "大寒吟", "text": "旧雪未及消，新雪又拥户。\n阶前冻银床，檐头冰钟乳。\n清日无光辉，烈风正号怒。\n人口各有舌，言语不能吐。", "img": "雪 风"}, {"dyn": "宋", "poet": "文同", "title": "和仲蒙夜坐", "text": "宿鸟惊飞断雁号，独凭幽几静尘劳。\n风鸣北户霜威重，云压南山雪意高。\n少睡始知茶效力，大寒须遣酒争豪。\n砚冰已合灯花老，犹对群书拥敝袍。", "img": "鸟 雁 霜 雪 风"}, {"dyn": "宋", "poet": "曾巩", "title": "元沙院", "text": "升山南下一峰高，上尽层轩未厌劳。\n际海烟云常惨澹，大寒松竹更萧骚。\n经台日永销香篆，谈席风生落麈毛。\n我亦有心从自得，琉璃瓶水照秋毫。", "img": "松竹 烟云"}, {"dyn": "宋", "poet": "陆游", "title": "大寒", "text": "大寒雪未消，闭户不能出。\n可怜切云冠，局此容膝室。\n吾车适已悬，吾驭久罢叱。\n拂麈取一编，相对辄终日。\n亡羊戒多岐，学道当致一。\n信能宗阙里，百氏端可黜。\n为山傥勿休，会见高崒嵂。\n颓龄虽已迫，孺子有美质。", "img": "雪"}, {"dyn": "宋", "poet": "黄庭坚", "title": "岁寒知松柏", "text": "松柏天生独，青青贯四时。\n心藏后凋节，岁有大寒知。", "img": "松柏"}, {"dyn": "宋", "poet": "陈著", "title": "游慈云", "text": "老怀不与世情更，才说闲行兴翼然。\n微湿易乾沙软路，大寒却暖雪晴天。\n未曾到寺香先妙，底用寻梅山自妍。\n笑问松边人立石，汝知今日是何年。", "img": "雪 梅"}, {"dyn": "明", "poet": "张嗣纲", "title": "山居大寒雪", "text": "山居逢岁腊，衣薄觉严寒。\n折竹声催听，飞禽影断看。\n僮仆痴环户，牛羊懒出栏。\n最愁无旨酒，邻舍不相干。", "img": "竹 飞禽 牛羊"}, {"dyn": "明", "poet": "庄昶", "title": "辛亥大寒梁塘道中有作·其一", "text": "春暖秋凉自不难，梅花何爱雪边看。\n自知不及尧夫老，今日梁塘是大寒。", "img": "梅花 雪"}], "stats": [], "emotion": "这组大寒诗词以积雪、北风、冰棱、松竹、早梅、归雁等物候意象为载体，情感层次丰富。大寒正值冬尽春临，酷寒之中已有梅柳静待阳春，常唤起诗人对时序轮转、春气将近的体察；凛冽风雪、冰封万物的景象，既生出闭门拥炉、读书饮酒的安闲，也有诗人目睹百姓在寒冬里饥寒交迫，满怀悲悯愧疚。还有人借松柏凌寒长青赞美坚贞节操，或是于寒日山行，享受清净悠然之趣，不同的人生境遇，让同一组大寒物候承载了迥然相异的情绪。", "culture": "这组诗作紧扣大寒冬春交接的节令特征，捕捉阴寒鼎盛、风雪频作、坚冰凝冻、梅蓄春意、松柏耐寒的物候变化，记录烈风、寒云、冷日等天象，是古人依靠自然征象感知岁末节气流转的体现。诗作延续寒冬咏物传统，松竹梅是君子风骨的经典象征，同时融入岁腊习俗、民生关怀，大寒风物成为媒介，承载着古人对阴阳交替、民瘼疾苦与人格坚守的理解。"}], "fanli": [["朝代限定", "仅收唐、宋、元、明、清五朝作品；先秦、汉魏六朝、金代（除元好问跨代外）及近现代作品不收。"], ["体裁", "诗、词、散曲不限：古体、近体、五七言、词牌皆入，唯以与节气相关为准。"], ["收录标准", "满足其一即可：①诗题明标节气（如《立春偶成》《清明》《谷雨》）；②诗句明写节气名（如“微雨众卉新，一雷惊蛰始”）；③诗中内容明显描写该节气物候节俗。"], ["收录数量", "共 83 首，每节气约 10-12 首（立春12、雨水11、惊蛰10、春分10、清明11、谷雨10、立夏9、小满10）。"], ["收录范围", "芒种、夏至、小暑、大暑、立秋、处暑、白露、秋分，共八个节气。"], ["朝代限定", "仅收唐、宋、元、明、清五朝作品；先秦、汉魏六朝、金代及近现代作品一律不收。"], ["体裁", "诗、词、散曲不限：古体、近体、五七言、六言、四言、词牌皆入，唯以与节气相关为准。"], ["收录标准", "满足其一即可：①诗题明标节气（如《立秋》《处暑后风雨》《夏至进宫斋戒舟过万泉庄》）；②诗句明写节气名（如“小暑才交雨渐晴”“时辰小暑绿新荷”“转毂年光逢小暑”“秋分客尚在”“芒种看今日”）；③通篇以该节气核心物候为描写对象（如芒种插秧收麦、夏至一阴生、大暑腐草为萤、白露凝露、秋分昼夜均平）。"], ["收录数量", "共 90 首（芒种 15、夏至 15、小暑 12、大暑 8、立秋 9、处暑 8、白露 12、秋分 11）；朝代分布为唐 19 首、宋 21首、元 14 首、明 15 首、清 21 首。"], ["收录范围", "寒露、霜降、立冬、小雪、大雪、冬至、小寒、大寒，共八个节气。与前卷（芒种—秋分）相接，合成二十四节气中的秋冬一段。"], ["朝代限定", "仅收唐、宋、元、明、清五朝作品；先秦、汉魏六朝、金代及近现代作品一律不收。"], ["体裁", "诗、词、散曲不限：古体、近体、五七言、六言、四言、词牌皆入，唯以与节气相关为准。"], ["收录标准", "满足其一即可：①诗题明标节气（如《寒露》《霜降》《立冬即事》《小雪》《江雪》《冬至吟》《小寒节有感》《大寒吟》）；②诗句明写节气名（如“寒露入暮愁衣单”“霜降天宇晶”“小雪晴沙不作泥”“冬至阳生春又来”“小寒连大吕”）；③通篇以该节气的核心物候为描写对象（如寒露凝露、霜降结霜、立冬薄冰、小雪飞霰、大雪封河、冬至长夜、小寒鹊巢、大寒冰乳）。"], ["收录数量", "共 97 首：寒露 12、霜降 13、立冬 12、小雪 11、大雪 13、冬至 12、小寒 13、大寒 11。各节气均在 8—15 首区间内，因寒露至大寒一段可考的元、清两代节气诗明显少于唐宋，未按每节气 15 首强行凑数，宁缺毋滥。朝代分布为唐 42 首、宋 35首、元 7 首、明 11 首、清 2 首。"]]};